css:
:root{
  --green:#0B5D3B; --green-d:#06331F; --green-dd:#042418; --green-l:#12764C; --green-x:#2FA46F;
  --teal:#0E7C6B; --teal-l:#14A08B;
  --gold:#B8901F; --gold-l:#D9B54A; --gold-bg:#FBF3DC; --gold-br:#EAD9A6;
  --mint:#E9F5ED; --mint-2:#D7ECE0; --mint-3:#BFDFCE;
  --ink:#12211A; --ink-2:#3C5347; --ink-3:#6A7C72; --ink-4:#95A39B;
  --cream:#FAF7EF; --cream-2:#F4EFE2; --card:#FFFFFF;
  --line:#E7E2D5; --line-2:#D8D2C2; --line-g:#DCE8E1;
  --ok:#17794E; --ok-bg:#E6F4EC; --ok-br:#BEE1CD;
  --warn:#9A6B05; --warn-bg:#FBF1DA; --warn-br:#EBD8A6;
  --crit:#9E2C22; --crit-bg:#FAE9E6; --crit-br:#EEC5BE;
  --info:#1E4E86; --info-bg:#E9F0F9; --info-br:#C6D8EE;
  --sp:#5F3C93; --sp-bg:#F0EAFA; --sp-br:#D9CBF0;
  --r:10px; --r-s:7px; --r-xs:5px;
  --sh:0 1px 2px rgba(18,33,26,.05),0 2px 6px rgba(18,33,26,.05);
  --sh-2:0 4px 16px rgba(18,33,26,.10);
  --sh-3:0 18px 48px rgba(6,35,22,.28);
  --sans:"Segoe UI",Inter,-apple-system,BlinkMacSystemFont,Roboto,"Helvetica Neue",Arial,sans-serif;
  --serif:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,"Times New Roman",serif;
  --mono:"SF Mono",ui-monospace,"Cascadia Mono",Consolas,monospace;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0;max-width:100%}
body{background:var(--cream);color:var(--ink);font-family:var(--sans);font-size:13.8px;line-height:1.5;-webkit-font-smoothing:antialiased}
button,input,select,textarea{font-family:inherit;font-size:inherit;color:inherit}
:focus-visible{outline:2px solid var(--gold);outline-offset:1px}
.tnum{font-variant-numeric:tabular-nums}
.mono{font-family:var(--mono);font-size:11.8px;letter-spacing:-.2px}
.ser{font-family:var(--serif)}
hr,.sep{border:0;border-top:1px solid var(--line);width:100%;max-width:100%;margin:12px 0}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

/* ============ MASTHEAD ============ */
.mast{position:sticky;top:0;z-index:80;background:linear-gradient(120deg,#06331F 0%,#0B5D3B 46%,#0E6B44 100%);
  color:#EAF4EE;display:flex;align-items:center;gap:14px;padding:0 16px;height:60px;
  box-shadow:0 1px 0 rgba(255,255,255,.09) inset,0 3px 14px rgba(6,35,22,.28)}
.logo{display:flex;align-items:center;gap:9px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.14);
  border-radius:9px;padding:6px 11px;box-shadow:inset 0 1px 0 rgba(255,255,255,.16)}
.logo b{font-family:var(--serif);font-size:19px;letter-spacing:.16em;color:#fff;line-height:1}
.logo i{width:7px;height:7px;border-radius:2px;background:linear-gradient(150deg,#F2D98A,#B8901F);
  box-shadow:0 1px 2px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.6);display:block}
.mast .home{display:flex;align-items:center;gap:7px;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.15);
  border-radius:8px;padding:7px 12px;font-size:13px;cursor:pointer;color:#EAF4EE;font-weight:600}
.mast .home:hover{background:rgba(255,255,255,.16)}
.mast .ttl{flex:1;text-align:center;min-width:0}
.mast .ttl b{display:block;font-family:var(--serif);font-size:20px;letter-spacing:.16em;color:#fff;font-weight:600;line-height:1.15}
.mast .ttl span{display:block;font-size:9.5px;letter-spacing:.34em;color:#9FCDB4;margin-top:3px;text-transform:uppercase}
.mast .user{display:flex;align-items:center;gap:9px;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.15);
  border-radius:22px;padding:5px 14px 5px 5px;cursor:pointer}
.mast .user:hover{background:rgba(255,255,255,.16)}
.mast .user .av{width:30px;height:30px;border-radius:50%;background:linear-gradient(150deg,#2FA46F,#0B5D3B);
  display:grid;place-items:center;font-size:11.5px;font-weight:800;color:#fff;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 2px 5px rgba(0,0,0,.3)}
.mast .user b{display:block;font-size:12.5px;color:#fff;line-height:1.2}
.mast .user span{display:block;font-size:9px;letter-spacing:.14em;color:#9FCDB4;text-transform:uppercase}
@media(max-width:900px){.mast .ttl,.mast .user span{display:none}.mast{height:54px}}

/* ============ 3D ICON CHIPS ============ */
.ic{width:26px;height:26px;flex:0 0 26px;border-radius:8px;display:grid;place-items:center;font-size:12.5px;
  color:#fff;background:linear-gradient(155deg,#2FA46F,#0B5D3B);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.42),inset 0 -2px 4px rgba(0,0,0,.22),0 2px 5px rgba(6,35,22,.3);
  font-style:normal;line-height:1}
.ic.gold{background:linear-gradient(155deg,#E8C868,#A87C12)}
.ic.teal{background:linear-gradient(155deg,#28BFA9,#0B6155)}
.ic.blue{background:linear-gradient(155deg,#5A93D6,#1B4278)}
.ic.plum{background:linear-gradient(155deg,#9A78D1,#4A2C7C)}
.ic.rose{background:linear-gradient(155deg,#DE7A6C,#8A2419)}
.ic.amber{background:linear-gradient(155deg,#F0BC5E,#96650A)}
.ic.slate{background:linear-gradient(155deg,#8FA79A,#3C5347)}
.ic.lg{width:34px;height:34px;flex:0 0 34px;border-radius:10px;font-size:16px}
.ic.sm{width:20px;height:20px;flex:0 0 20px;border-radius:6px;font-size:10px}

/* ============ SHELL ============ */
.app{display:flex;min-height:calc(100vh - 60px);max-width:100%}
.side{width:236px;flex:0 0 236px;background:linear-gradient(180deg,#06331F,#042418);color:#CFE3D8;
  display:flex;flex-direction:column;position:sticky;top:60px;height:calc(100vh - 60px)}
.side-h{padding:13px 16px 10px;border-bottom:1px solid rgba(255,255,255,.08);display:flex;align-items:center;gap:9px}
.side-h b{font-size:10px;letter-spacing:.22em;color:#8FBBA4;text-transform:uppercase;font-weight:800}
.side-s{padding:10px 14px 6px}
.side-s input{width:100%;padding:7px 10px;border-radius:8px;border:1px solid rgba(255,255,255,.13);
  background:rgba(255,255,255,.06);color:#EAF4EE;font-size:12.5px}
.side-s input::placeholder{color:#7FA894}
.nav{flex:1;overflow-y:auto;padding:4px 8px 16px}
.nav::-webkit-scrollbar{width:6px}.nav::-webkit-scrollbar-thumb{background:rgba(255,255,255,.14);border-radius:6px}
.ngrp{margin-bottom:3px}
.ghead{display:flex;align-items:center;gap:9px;padding:8px 8px;border-radius:9px;cursor:pointer;user-select:none}
.ghead:hover{background:rgba(255,255,255,.06)}
.ghead b{flex:1;font-size:11.5px;letter-spacing:.11em;text-transform:uppercase;font-weight:750;color:#DCEBE3}
.ghead .n{background:rgba(255,255,255,.13);color:#CFE3D8;border-radius:6px;font-size:10px;font-weight:800;padding:1px 6px}
.ghead .cv{font-size:9px;color:#7FA894;transition:transform .18s}
.ngrp.open .ghead{background:rgba(255,255,255,.09)}
.ngrp.open .ghead .cv{transform:rotate(90deg)}
.gitems{display:none;padding:3px 0 6px 20px;position:relative}
.ngrp.open .gitems{display:block}
.gitems::before{content:"";position:absolute;left:9px;top:2px;bottom:8px;width:1px;background:rgba(255,255,255,.13)}
.nav a{display:block;position:relative;padding:6px 9px 6px 14px;border-radius:7px;color:#B9D2C6;cursor:pointer;
  text-decoration:none;font-size:12.8px;line-height:1.35}
.nav a::before{content:"";position:absolute;left:-15px;top:12px;width:7px;height:7px;border-radius:50%;
  background:#0B5D3B;border:1.5px solid #58816C}
.nav a:hover{background:rgba(255,255,255,.07);color:#fff}
.nav a.on{background:rgba(255,255,255,.13);color:#fff;font-weight:650}
.nav a.on::before{background:var(--gold-l);border-color:#F2D98A;box-shadow:0 0 0 3px rgba(217,181,74,.18)}
.nav a span{display:block;font-size:10.5px;color:#7FA894;font-weight:400;margin-top:1px}
.nav a.on span{color:#A9CDBA}
.nav a .pill{position:absolute;right:8px;top:7px;background:var(--gold-l);color:#3A2B03;border-radius:9px;
  padding:0 6px;font-size:9.5px;font-weight:800;line-height:16px}
.nav a .pill.r{background:#E8A79E;color:#5E1610}
.side-f{padding:9px 14px;border-top:1px solid rgba(255,255,255,.08);font-size:10px;color:#6E9686;line-height:1.5}

.main{flex:1;min-width:0;display:flex;flex-direction:column}
.fbar{position:sticky;top:60px;z-index:60;background:var(--cream-2);border-bottom:1px solid var(--line);
  display:flex;align-items:center;gap:8px;padding:9px 16px;flex-wrap:wrap}
.fbar .lb{font-size:10.5px;letter-spacing:.15em;text-transform:uppercase;color:var(--ink-3);font-weight:800;margin-right:2px}
.fchip{display:inline-flex;align-items:center;gap:6px;background:#fff;border:1px solid var(--line-2);border-radius:7px;
  padding:5px 11px;font-size:12.3px;font-weight:600;cursor:pointer;box-shadow:var(--sh)}
.fchip:hover{border-color:var(--gold);background:var(--gold-bg)}
.fchip.on{background:var(--mint);border-color:var(--mint-3);color:var(--green)}
.fchip.gold{background:var(--gold-bg);border-color:var(--gold-br);color:#7A5F09}
.fchip.lock{background:#F1EFE7;border-color:var(--line-2);color:var(--ink-3);cursor:default}
.fchip select{border:0;background:transparent;font-weight:700;cursor:pointer;padding:0}
.wrap{padding:16px;width:100%;max-width:1620px}
.view{display:none}
.view.on{display:block;animation:fade .18s ease}
@keyframes fade{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}

/* ============ PAGE HEADER ============ */
.ph{background:#fff;border:1px solid var(--line);border-left:4px solid var(--green);border-radius:var(--r);
  padding:14px 17px;margin-bottom:14px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;box-shadow:var(--sh)}
.ph h2{margin:0;font-family:var(--serif);font-size:25px;font-weight:600;letter-spacing:-.01em;line-height:1.12}
.ph p{margin:5px 0 0;font-size:12.8px;color:var(--ink-3);max-width:820px}
.ph .kicker{font-size:10px;letter-spacing:.19em;text-transform:uppercase;color:var(--gold);font-weight:800;margin-bottom:3px}
.ph .sp{flex:1}
.back{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;color:var(--green);cursor:pointer;font-weight:650;margin-bottom:9px}
.back:hover{text-decoration:underline}
.crumb{font-size:11.5px;color:var(--ink-3);margin-bottom:8px}
.crumb b{color:var(--ink-2)}

/* ============ SECTION HEADERS ============ */
.shead{display:flex;align-items:center;gap:10px;margin:16px 0 10px;padding:0 2px}
.shead .cv{color:var(--ink-3);font-size:10px}
.shead .ltr{width:19px;height:19px;border-radius:5px;background:var(--gold-bg);border:1px solid var(--gold-br);
  color:#7A5F09;font-size:10.5px;font-weight:800;display:grid;place-items:center;font-family:var(--serif)}
.shead b{font-family:var(--serif);font-size:17.5px;font-weight:600}
.shead .sub{font-size:12px;color:var(--ink-3)}
.shead .sp{flex:1}

/* ============ CARDS ============ */
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);margin-bottom:14px;overflow:hidden;max-width:100%}
.card>header{display:flex;align-items:center;gap:10px;padding:11px 14px;border-bottom:1px solid var(--line);background:linear-gradient(180deg,#FFFDF8,#FAF7EF)}
.card>header h3{margin:0;font-size:14.5px;font-weight:700;letter-spacing:-.005em;font-family:var(--serif)}
.card>header .sub{font-size:11.8px;color:var(--ink-3);font-weight:400}
.card>header .sp{flex:1}
.card>.body{padding:14px}
.card>.body.flush{padding:0}
.card.acc{border-left:4px solid var(--green)}
.card.acc>header{background:linear-gradient(120deg,#06331F,#0B5D3B)}
.card.acc>header h3{color:#fff}
.card.acc>header .sub{color:#A9CDBA}
.card.acc-g{border-left:4px solid var(--gold)}
.card.acc-g>header{background:linear-gradient(180deg,#FBF3DC,#F6EAC8)}
.card.acc-t{border-left:4px solid var(--teal)}
.card.acc-t>header{background:linear-gradient(120deg,#0B6155,#0E7C6B)}
.card.acc-t>header h3{color:#fff}
.card.acc-t>header .sub{color:#B9E4DC}
.card.acc-r{border-left:4px solid var(--crit)}
.card.acc-r>header{background:linear-gradient(120deg,#8A2419,#B8443A)}
.card.acc-r>header h3{color:#fff}
.card.acc-r>header .sub{color:#F3CFC9}

.grid{display:grid;gap:12px;max-width:100%}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
.g5{grid-template-columns:repeat(5,minmax(0,1fr))}
.g6{grid-template-columns:repeat(6,minmax(0,1fr))}
.g7{grid-template-columns:repeat(7,minmax(0,1fr))}
.g-21{grid-template-columns:2fr 1fr}
.g-12{grid-template-columns:1fr 2fr}
@media(max-width:1400px){.g7{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:1240px){.g6,.g5{grid-template-columns:repeat(3,minmax(0,1fr))}.g4{grid-template-columns:repeat(2,minmax(0,1fr))}.g-21,.g-12{grid-template-columns:1fr}}
#menub{display:none}
@media(max-width:880px){.side{display:none}#menub{display:inline-flex}
 .side.show{display:flex;position:fixed;top:60px;left:0;bottom:0;z-index:120;width:250px;box-shadow:var(--sh-3)}.g2,.g3,.g4,.g5,.g6,.g7{grid-template-columns:1fr}}

/* ============ KPI TILES ============ */
.tile{background:#fff;border:1px solid var(--line);border-left:3px solid var(--green);border-radius:var(--r-s);
  padding:13px 14px 14px;box-shadow:var(--sh);cursor:pointer;transition:transform .13s,box-shadow .13s;position:relative;overflow:hidden}
.tile:hover{transform:translateY(-2px);box-shadow:var(--sh-2)}
.tile .v{font-family:var(--serif);font-size:27px;font-weight:600;letter-spacing:-.01em;line-height:1.05;color:var(--green)}
.tile .k{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-2);font-weight:750;margin-top:6px}
.tile .d{font-size:11.5px;color:var(--ink-3);margin-top:3px}
.tile.t-gold{border-left-color:var(--gold)} .tile.t-gold .v{color:var(--gold)}
.tile.t-crit{border-left-color:var(--crit)} .tile.t-crit .v{color:var(--crit)}
.tile.t-warn{border-left-color:#C98A0B} .tile.t-warn .v{color:var(--warn)}
.tile.t-ok{border-left-color:var(--ok)} .tile.t-ok .v{color:var(--ok)}
.tile.t-info{border-left-color:var(--info)} .tile.t-info .v{color:var(--info)}
.tile.t-teal{border-left-color:var(--teal)} .tile.t-teal .v{color:var(--teal)}
.tile.t-sp{border-left-color:var(--sp)} .tile.t-sp .v{color:var(--sp)}
.bigval{background:linear-gradient(125deg,#06331F,#0B5D3B 60%,#0E6B44);color:#fff;border-radius:var(--r);padding:14px 16px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.14),var(--sh-2);position:relative;overflow:hidden}
.bigval::after{content:"";position:absolute;right:-30px;top:-30px;width:110px;height:110px;border-radius:50%;background:rgba(255,255,255,.05)}
.bigval .v{font-family:var(--serif);font-size:31px;font-weight:600;line-height:1.08}
.bigval .k{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#A9CDBA;font-weight:800;margin-top:5px}
.bigval .d{font-size:11.8px;color:#CFE3D8;margin-top:4px}

/* ============ BADGES ============ */
.tag{display:inline-flex;align-items:center;gap:5px;padding:1px 9px;border-radius:20px;font-size:10.8px;font-weight:750;line-height:19px;white-space:nowrap;border:1px solid transparent}
.t-g{background:var(--ok-bg);color:var(--ok);border-color:var(--ok-br)}
.t-y{background:var(--warn-bg);color:var(--warn);border-color:var(--warn-br)}
.t-r{background:var(--crit-bg);color:var(--crit);border-color:var(--crit-br)}
.t-b{background:var(--info-bg);color:var(--info);border-color:var(--info-br)}
.t-p{background:var(--sp-bg);color:var(--sp);border-color:var(--sp-br)}
.t-n{background:#F1EFE7;color:var(--ink-2);border-color:var(--line-2)}
.t-m{background:var(--mint);color:var(--green);border-color:var(--mint-3)}
.t-au{background:var(--gold-bg);color:#7A5F09;border-color:var(--gold-br)}
.dot{width:6px;height:6px;border-radius:50%;background:currentColor;display:inline-block}

/* ============ BUTTONS ============ */
.btn{display:inline-flex;align-items:center;gap:6px;padding:6px 13px;border:1px solid var(--line-2);background:#fff;border-radius:var(--r-xs);cursor:pointer;font-size:12.4px;font-weight:650;transition:.12s;white-space:nowrap;box-shadow:var(--sh)}
.btn:hover{background:var(--cream);border-color:var(--ink-4)}
.btn.p{background:linear-gradient(160deg,#12764C,#0B5D3B);border-color:#0B5D3B;color:#fff;box-shadow:inset 0 1px 0 rgba(255,255,255,.18),var(--sh)}
.btn.p:hover{filter:brightness(1.09)}
.btn.g{background:linear-gradient(160deg,#D9B54A,#B8901F);border-color:#A87C12;color:#3A2B03}
.btn.g:hover{filter:brightness(1.06)}
.btn.s{background:linear-gradient(160deg,#14A08B,#0B6155);border-color:#0B6155;color:#fff}
.btn.d{background:linear-gradient(160deg,#B8443A,#9E2C22);border-color:#9E2C22;color:#fff}
.btn.sm{padding:3px 9px;font-size:11.4px}
.btn.lg{padding:10px 20px;font-size:14px}
.btn:disabled{opacity:.45;cursor:not-allowed}
.btnrow{display:flex;gap:8px;flex-wrap:wrap;align-items:center}

/* ============ TABLES ============ */
.tw{width:100%;max-width:100%;overflow-x:auto}
table.tb{width:100%;border-collapse:collapse;font-size:13.2px}
table.tb th{background:#F6F2E6;color:var(--ink-2);font-size:10.5px;text-transform:uppercase;letter-spacing:.1em;font-weight:800;text-align:left;padding:9px 12px;border-bottom:1px solid var(--line-2);white-space:nowrap}
table.tb td{padding:9px 12px;border-bottom:1px solid var(--line-g);vertical-align:middle}
table.tb tbody tr:hover{background:var(--mint)}
table.tb tbody tr:nth-child(even){background:#FCFAF4}
table.tb tbody tr:nth-child(even):hover{background:var(--mint)}
table.tb td.r,table.tb th.r{text-align:right}
table.tb td.c,table.tb th.c{text-align:center}
table.tb tr.click{cursor:pointer}
table.tb tfoot td{background:var(--cream-2);font-weight:800;border-top:2px solid var(--line-2);padding:10px 12px}
.tb .nm{font-weight:650}
.tb .sm2{font-size:11.3px;color:var(--ink-3)}
.tb .big{font-family:var(--serif);font-size:15px;font-weight:600}
.pos{color:var(--ok);font-weight:700}
.neg{color:var(--crit);font-weight:700}
.amber{color:var(--warn);font-weight:700}
.blu{color:var(--info);font-weight:700}
.empty{padding:36px 16px;text-align:center;color:var(--ink-3)}
.empty b{display:block;font-size:14.5px;color:var(--ink-2);margin-bottom:4px;font-family:var(--serif)}
table.tb td input,table.tb td select{padding:5px 8px;border:1px solid var(--line-2);border-radius:var(--r-xs);width:100%;background:#fff}
table.tb td input.chg,table.tb td select.chg{border-color:var(--gold);background:var(--gold-bg);font-weight:700}

/* ============ FORMS ============ */
.filters{background:linear-gradient(180deg,#FFFDF8,#F6F2E6);border:1px solid var(--line);border-radius:var(--r);padding:12px 14px;margin-bottom:13px;display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end}
.fl{display:flex;flex-direction:column;gap:4px;min-width:135px}
.fl label{font-size:10px;text-transform:uppercase;letter-spacing:.11em;color:var(--ink-2);font-weight:800}
.fl input,.fl select,.fl textarea{padding:7px 10px;border:1px solid var(--line-2);border-radius:var(--r-xs);background:#fff;width:100%}
.fl input:focus,.fl select:focus{border-color:var(--teal)}
.fg{display:flex;flex-direction:column;gap:4px;margin-bottom:11px}
.fg label{font-size:11.5px;font-weight:700;color:var(--ink-2)}
.fg label .rq{color:var(--crit)}
.fg input,.fg select,.fg textarea{padding:8px 11px;border:1px solid var(--line-2);border-radius:var(--r-xs);background:#fff;width:100%}
.fg .hint{font-size:10.8px;color:var(--ink-3)}
.sec{display:flex;align-items:center;gap:9px;margin:16px 0 10px}
.sec b{font-size:15.5px;font-weight:650;font-family:var(--serif)}
.sec span{font-size:12px;color:var(--ink-3)}
.sec i{flex:1;height:1px;background:var(--line);display:block;max-width:100%}

/* ============ BLOCKS ============ */
.note{border-radius:var(--r-s);padding:11px 13px;font-size:12.6px;border:1px solid;line-height:1.55}
.note b{display:block;margin-bottom:2px;font-size:12.9px}
.n-i{background:var(--info-bg);border-color:var(--info-br);color:#173C68}
.n-w{background:var(--warn-bg);border-color:var(--warn-br);color:#6E4C05}
.n-c{background:var(--crit-bg);border-color:var(--crit-br);color:#7A211A}
.n-g{background:var(--ok-bg);border-color:var(--ok-br);color:#0F5636}
.n-m{background:var(--mint);border-color:var(--mint-3);color:var(--green)}
.n-p{background:var(--sp-bg);border-color:var(--sp-br);color:#452B6B}
.n-a{background:var(--gold-bg);border-color:var(--gold-br);color:#6E5407}
.kv{display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px dashed var(--line);font-size:12.8px}
.kv:last-child{border-bottom:0}
.kv span{color:var(--ink-3)}
.kv b{font-weight:700;text-align:right}
.stepbar{display:flex;gap:0;margin-bottom:14px;flex-wrap:wrap}
.stepbar div{flex:1;min-width:130px;padding:9px 11px;background:#fff;border:1px solid var(--line);border-right:0;font-size:12px;color:var(--ink-3);font-weight:650;cursor:default}
.stepbar div:last-child{border-right:1px solid var(--line);border-radius:0 var(--r-xs) var(--r-xs) 0}
.stepbar div:first-child{border-radius:var(--r-xs) 0 0 var(--r-xs)}
.stepbar div.on{background:linear-gradient(160deg,#12764C,#0B5D3B);color:#fff;border-color:#0B5D3B}
.stepbar div.dn{background:var(--mint);color:var(--green);border-color:var(--mint-3);cursor:pointer}
.stepbar div b{display:block;font-size:9.8px;text-transform:uppercase;letter-spacing:.1em;opacity:.85;font-weight:800}
.tabs{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:12px;border-bottom:1px solid var(--line)}
.tabs a{padding:7px 13px;font-size:12.8px;font-weight:650;color:var(--ink-3);cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px}
.tabs a:hover{color:var(--green)}
.tabs a.on{color:var(--green);border-bottom-color:var(--gold)}
.chip{display:inline-flex;align-items:center;gap:5px;padding:3px 11px;border-radius:20px;background:#fff;border:1px solid var(--line-2);font-size:11.5px;cursor:pointer;font-weight:650}
.chip:hover{background:var(--gold-bg);border-color:var(--gold-br)}
.chip.on{background:linear-gradient(160deg,#12764C,#0B5D3B);color:#fff;border-color:#0B5D3B}
.bar{height:7px;background:var(--cream-2);border-radius:20px;overflow:hidden;max-width:100%;border:1px solid var(--line)}
.bar i{display:block;height:100%;background:linear-gradient(90deg,#12764C,#2FA46F);border-radius:20px}
.bar i.w{background:linear-gradient(90deg,#C98A0B,#E5B441)} .bar i.c{background:linear-gradient(90deg,#9E2C22,#C4574A)}
.bar i.t{background:linear-gradient(90deg,#0B6155,#14A08B)} .bar i.gd{background:linear-gradient(90deg,#B8901F,#E2C25F)}
.tline{position:relative;padding-left:20px}
.tline .ev{position:relative;padding:0 0 13px 0;font-size:12.6px}
.tline .ev::before{content:"";position:absolute;left:-15px;top:5px;width:8px;height:8px;border-radius:50%;background:var(--green);border:2px solid #fff;box-shadow:0 0 0 1px var(--mint-3)}
.tline .ev.rj::before{background:var(--crit)} .tline .ev.qy::before{background:var(--gold)} .tline .ev.pd::before{background:var(--ink-4)}
.tline::before{content:"";position:absolute;left:-1px;top:6px;bottom:6px;width:1px;background:var(--line-2)}
.tline .ev .hd{font-weight:700}
.tline .ev .mt{font-size:11.3px;color:var(--ink-3)}
.tline .ev .bd{margin-top:3px;background:var(--cream-2);border:1px solid var(--line);border-radius:var(--r-xs);padding:7px 10px;font-size:12.2px}

/* workflow banner */
.wfb{display:flex;align-items:center;gap:12px;flex-wrap:wrap;background:linear-gradient(120deg,#06331F,#0B5D3B);color:#fff;
  border-radius:var(--r);padding:12px 15px;margin-bottom:13px;box-shadow:var(--sh-2)}
.wfb .lbl{font-size:9.5px;letter-spacing:.18em;text-transform:uppercase;color:#9FCDB4;font-weight:800}
.wfb .own{font-family:var(--serif);font-size:19px;font-weight:600;line-height:1.1}
.wfb .sp{flex:1}
.wfb.rj{background:linear-gradient(120deg,#7A211A,#B8443A)}
.wfb.ok{background:linear-gradient(120deg,#0F5636,#17794E)}
.wfb.qy{background:linear-gradient(120deg,#6E5407,#B8901F)}
.wfb .chain{display:flex;gap:6px;flex-wrap:wrap}
.wfb .chain i{font-style:normal;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);border-radius:20px;
  padding:2px 11px;font-size:11.2px;font-weight:700}
.wfb .chain i.dn{background:rgba(255,255,255,.9);color:#0B5D3B;border-color:#fff}
.wfb .chain i.cur{background:var(--gold-l);color:#3A2B03;border-color:#F2D98A}

/* diff table */
.dif{width:100%;border-collapse:collapse;font-size:12.8px}
.dif th{background:#F6F2E6;font-size:10px;text-transform:uppercase;letter-spacing:.1em;font-weight:800;text-align:left;padding:8px 10px;border-bottom:1px solid var(--line-2);color:var(--ink-2)}
.dif td{padding:8px 10px;border-bottom:1px solid var(--line-g);vertical-align:top}
.dif td.was{color:var(--ink-3);text-decoration:line-through}
.dif td.now{font-weight:750;color:var(--green)}
.dif td.rec{font-weight:750;color:var(--sp)}
.dif td.fin{font-weight:800;color:#3A2B03;background:var(--gold-bg)}
.dif tr:nth-child(even) td{background:#FCFAF4}
.dif tr:nth-child(even) td.fin{background:#F6EAC8}

/* login */
#login{position:fixed;inset:0;background:linear-gradient(140deg,#042418,#0B5D3B 65%,#0E6B44);z-index:500;display:grid;place-items:center;padding:20px}
#login .box{background:#fff;border-radius:16px;box-shadow:var(--sh-3);width:100%;max-width:660px;overflow:hidden}
#login .box>header{background:linear-gradient(120deg,#06331F,#0B5D3B);color:#fff;padding:18px 22px;display:flex;align-items:center;gap:12px}
#login .box>header b{font-family:var(--serif);font-size:22px;letter-spacing:.14em}
#login .box>header span{font-size:10px;letter-spacing:.3em;color:#9FCDB4;text-transform:uppercase;display:block;margin-top:3px}
#login .box>.b{padding:18px 22px 22px}
.ucard{display:flex;gap:11px;align-items:center;border:1px solid var(--line);border-radius:var(--r);padding:10px 12px;cursor:pointer;background:#fff;transition:.12s}
.ucard:hover{border-color:var(--gold);background:var(--gold-bg);transform:translateY(-1px)}
.ucard .av{width:36px;height:36px;border-radius:50%;background:linear-gradient(150deg,#2FA46F,#0B5D3B);color:#fff;display:grid;place-items:center;font-weight:800;font-size:12.5px;flex:0 0 36px}
.ucard b{display:block;font-size:13.4px}
.ucard span{display:block;font-size:11.3px;color:var(--ink-3)}


/* ============ CATEGORY CARDS (step 1) ============ */
.dcard{background:#fff;border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden;display:flex;flex-direction:column;transition:.14s}
.dcard:hover{box-shadow:var(--sh-2);border-color:var(--line-2)}
.dcard.sel{border-color:var(--gold);box-shadow:0 0 0 2px rgba(184,144,31,.22),var(--sh-2)}
.dcard>header{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line);
  background:linear-gradient(120deg,#06331F,#0B5D3B);color:#fff}
.dcard>header h3{margin:0;font-family:var(--serif);font-size:15.5px;font-weight:600;line-height:1.15}
.dcard>header .sub{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#9FCDB4;font-weight:800;margin-top:2px}
.dcard.sel>header{background:linear-gradient(120deg,#6E5407,#B8901F)}
.dcard .dbody{padding:11px 13px;flex:1}
.dcard .exp{font-size:12.2px;color:var(--ink-2);line-height:1.55;margin-bottom:9px}
.dcard .dfoot{border-top:1px solid var(--line);background:var(--cream-2);padding:8px 13px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:11px;color:var(--ink-3)}
.opt{display:flex;align-items:flex-start;gap:9px;padding:7px 9px;border:1px solid var(--line);border-radius:var(--r-s);
  margin-bottom:6px;cursor:pointer;background:#FCFAF4;transition:.12s}
.opt:hover{background:var(--mint);border-color:var(--mint-3)}
.opt.on{background:var(--gold-bg);border-color:var(--gold-br);box-shadow:inset 0 0 0 1px var(--gold-br)}
.opt .rd{width:15px;height:15px;flex:0 0 15px;border-radius:50%;border:2px solid var(--ink-4);margin-top:2px;display:grid;place-items:center;background:#fff}
.opt.on .rd{border-color:var(--gold)}
.opt.on .rd::after{content:"";width:7px;height:7px;border-radius:50%;background:var(--gold)}
.opt b{display:block;font-size:12.7px;font-weight:700;line-height:1.3}
.opt span{display:block;font-size:11.2px;color:var(--ink-3);margin-top:1px;line-height:1.45}

/* ============ PROGRESS (n of m) ============ */
.prog{display:inline-flex;align-items:center;gap:7px;white-space:nowrap}
.prog .cnt{font-family:var(--serif);font-size:13px;font-weight:700;color:var(--green)}
.prog .seg{display:flex;gap:2px}
.prog .seg i{width:14px;height:5px;border-radius:3px;background:var(--line-2);display:block}
.prog .seg i.dn{background:linear-gradient(90deg,#12764C,#2FA46F)}
.prog .seg i.cur{background:var(--gold-l);box-shadow:0 0 0 1px var(--gold)}
.prog .seg i.rj{background:var(--crit)}
.prog .nx{font-size:10.8px;color:var(--ink-3)}
.prog.done .cnt{color:var(--ok)}
.prog.rj .cnt{color:var(--crit)}

/* ============ HOLD BADGE ============ */
.hold{display:inline-flex;align-items:center;gap:5px;background:repeating-linear-gradient(135deg,#FBF1DA,#FBF1DA 6px,#F6E6BE 6px,#F6E6BE 12px);
  border:1px solid var(--warn-br);color:#6E4C05;border-radius:6px;padding:1px 8px;font-size:10.5px;font-weight:800;letter-spacing:.03em}
tr.held{opacity:.72}
tr.held td{background:#FDF8EC!important}

/* ============ AI UPLOAD VERIFICATION ============ */
.aiv{border-radius:var(--r-s);border:1px solid;padding:11px 13px;display:flex;gap:11px;align-items:flex-start}
.aiv .ico{width:34px;height:34px;flex:0 0 34px;border-radius:9px;display:grid;place-items:center;font-size:16px;color:#fff}
.aiv.ok{background:var(--ok-bg);border-color:var(--ok-br)} .aiv.ok .ico{background:linear-gradient(155deg,#2FA46F,#0B5D3B)}
.aiv.wn{background:var(--warn-bg);border-color:var(--warn-br)} .aiv.wn .ico{background:linear-gradient(155deg,#F0BC5E,#96650A)}
.aiv.rj{background:var(--crit-bg);border-color:var(--crit-br)} .aiv.rj .ico{background:linear-gradient(155deg,#DE7A6C,#8A2419)}
.aiv b{display:block;font-size:13px;margin-bottom:2px}
.aiv .ln{font-size:11.9px;color:var(--ink-2);line-height:1.5}
.conf{display:flex;align-items:center;gap:8px;margin-top:6px}
.conf .bb{flex:1;max-width:190px;height:6px;background:#fff;border:1px solid var(--line-2);border-radius:20px;overflow:hidden}
.conf .bb i{display:block;height:100%;background:linear-gradient(90deg,#12764C,#2FA46F)}
.conf.wn .bb i{background:linear-gradient(90deg,#C98A0B,#E5B441)}
.conf.rj .bb i{background:linear-gradient(90deg,#9E2C22,#C4574A)}
.conf span{font-size:10.8px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-2)}
.filechip{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line-2);background:#fff;border-radius:7px;
  padding:5px 10px;font-size:11.8px;cursor:pointer;margin:0 5px 5px 0;font-weight:600}
.filechip:hover{border-color:var(--gold);background:var(--gold-bg)}
.filechip i{font-style:normal;font-size:13px}

/* ============ GUIDE ============ */
.guide{display:grid;gap:0;border:1px solid var(--line);border-radius:var(--r);overflow:hidden;background:#fff}
.guide .row{
  display:flex!important;
  gap:12px!important;
  padding:10px 13px!important;
  margin:0!important;
  width:100%!important;
  max-width:100%!important;
  border-bottom:1px solid var(--line-g);
  align-items:flex-start!important;
  flex-wrap:nowrap!important;
  box-sizing:border-box!important
}
.guide .row:last-child{border-bottom:0}
.guide .row:nth-child(even){background:#FCFAF4}
.guide .row .n{
  width:22px!important;
  height:22px!important;
  flex:0 0 22px!important;
  margin:0!important;
  border-radius:6px;
  background:var(--mint);
  border:1px solid var(--mint-3);
  color:var(--green);
  font-weight:800;
  font-size:11px;
  display:grid!important;
  place-items:center!important;
  font-family:var(--serif);
  box-sizing:border-box!important
}
.guide .row b{display:block;font-size:12.9px}
.guide .row span{display:block;font-size:12px;color:var(--ink-3);margin-top:2px;line-height:1.5}

/* ============ MODAL ============ */
/*
   IMPORTANT:
   Frappe/Bootstrap also defines a global `.modal` class with display:none
   and fixed positioning. Keep these selectors strongly scoped so LIFE DCR's
   modal cannot be hidden or moved by website.css/bootstrap.css.
*/
html.life-dcr-modal-open,
body.life-dcr-modal-open{overflow:hidden!important}

#life-dcr-root #ov.ov{
  position:fixed!important;
  inset:0!important;
  width:100vw!important;
  height:100dvh!important;
  margin:0!important;
  background:rgba(6,35,22,.58)!important;
  display:none!important;
  align-items:center!important;
  justify-content:center!important;
  z-index:2147483000!important;
  padding:22px 16px!important;
  overflow:auto!important;
  overscroll-behavior:contain;
  backdrop-filter:blur(3px);
  -webkit-backdrop-filter:blur(3px);
}

#life-dcr-root #ov.ov.on{
  display:flex!important;
}

#life-dcr-root #modal.modal{
  position:relative!important;
  inset:auto!important;
  top:auto!important;
  right:auto!important;
  bottom:auto!important;
  left:auto!important;
  display:flex!important;
  flex-direction:column!important;
  visibility:visible!important;
  opacity:1!important;
  float:none!important;
  width:min(900px,calc(100vw - 32px))!important;
  height:auto!important;
  max-height:calc(100dvh - 44px)!important;
  margin:auto!important;
  padding:0!important;
  overflow:hidden!important;
  pointer-events:auto!important;
  transform:none;
  background:#fff!important;
  border:1px solid rgba(10,75,48,.14)!important;
  border-radius:14px!important;
  box-shadow:0 28px 80px rgba(4,34,21,.35)!important;
  animation:lifeDcrPop .17s ease;
  z-index:1!important;
}

#life-dcr-root #modal.modal.wide{
  width:min(1180px,calc(100vw - 32px))!important;
  max-width:1180px!important;
}

#life-dcr-root #modal.modal.narrow{
  width:min(540px,calc(100vw - 32px))!important;
  max-width:540px!important;
}

@keyframes lifeDcrPop{
  from{opacity:0;transform:scale(.985) translateY(8px)}
  to{opacity:1;transform:none}
}

#life-dcr-root #modal.modal>header{
  position:relative!important;
  flex:0 0 auto!important;
  display:flex!important;
  align-items:center!important;
  gap:12px!important;
  padding:14px 18px!important;
  margin:0!important;
  background:linear-gradient(110deg,#0C6942,#15855A 60%,#2AA372)!important;
  color:#fff!important;
  border:0!important;
}

#life-dcr-root #modal.modal>header h3{
  margin:0!important;
  font-size:17.5px!important;
  font-weight:600!important;
  font-family:var(--serif)!important;
  color:#fff!important;
}

#life-dcr-root #modal.modal>header .sub{
  margin-top:2px;
  font-size:11.5px!important;
  color:#D0EBDD!important;
}

#life-dcr-root #modal.modal>header .sp{flex:1!important}

#life-dcr-root #modal.modal>header .x{
  width:34px!important;
  height:34px!important;
  flex:0 0 34px!important;
  display:grid!important;
  place-items:center!important;
  padding:0!important;
  margin:0!important;
  border:1px solid rgba(255,255,255,.25)!important;
  border-radius:9px!important;
  background:rgba(255,255,255,.10)!important;
  color:#fff!important;
  cursor:pointer!important;
  font-size:24px!important;
  line-height:1!important;
  opacity:1!important;
  user-select:none;
}

#life-dcr-root #modal.modal>header .x:hover{
  background:rgba(255,255,255,.20)!important;
}

#life-dcr-root #modal.modal>.body{
  position:relative!important;
  flex:1 1 auto!important;
  min-height:0!important;
  max-height:none!important;
  padding:17px!important;
  margin:0!important;
  overflow:auto!important;
  overscroll-behavior:contain;
  background:#fff!important;
  color:var(--ink)!important;
}

#life-dcr-root #modal.modal>footer{
  position:relative!important;
  flex:0 0 auto!important;
  display:flex!important;
  gap:9px!important;
  justify-content:flex-end!important;
  align-items:center!important;
  padding:12px 18px!important;
  margin:0!important;
  border-top:1px solid var(--line)!important;
  background:var(--cream)!important;
  flex-wrap:wrap!important;
}

@media(max-width:700px){
  #life-dcr-root #ov.ov{
    align-items:flex-end!important;
    padding:10px!important;
  }

  #life-dcr-root #modal.modal,
  #life-dcr-root #modal.modal.wide,
  #life-dcr-root #modal.modal.narrow{
    width:100%!important;
    max-width:100%!important;
    max-height:calc(100dvh - 20px)!important;
    border-radius:14px 14px 10px 10px!important;
  }

  #life-dcr-root #modal.modal>.body{
    padding:12px!important;
  }
}

/* ============ TOAST ============ */
#toast{position:fixed;right:18px;bottom:18px;z-index:400;display:flex;flex-direction:column;gap:8px}
.tst{background:linear-gradient(160deg,#12211A,#06331F);color:#fff;padding:11px 16px;border-radius:9px;font-size:12.8px;box-shadow:var(--sh-3);animation:sl .18s ease;max-width:340px;border-left:3px solid var(--gold)}
.tst.ok{border-left-color:#2FA46F} .tst.err{border-left-color:#C4574A} .tst.wn{border-left-color:#E5B441}
@keyframes sl{from{opacity:0;transform:translateX(14px)}to{opacity:1;transform:none}}

/* ============ PRINT DOCUMENT (A4) ============ */
#prn{display:none}
.doc{width:100%;max-width:794px;margin:0 auto;background:#fff;color:#12211A;font-size:12px;padding:0}
.doc .dh{display:flex;align-items:flex-start;gap:14px;border-bottom:2.5px solid #0B5D3B;padding-bottom:10px;margin-bottom:12px}
.doc .dh .lg2{font-family:var(--serif);font-size:26px;letter-spacing:.18em;color:#0B5D3B;font-weight:700;line-height:1}
.doc .dh .co{font-size:10px;color:#3C5347;margin-top:4px;line-height:1.45}
.doc .dh .rt{margin-left:auto;text-align:right}
.doc .dh .rt b{display:block;font-family:var(--serif);font-size:16px;color:#0B5D3B}
.doc .dh .rt span{font-size:10.5px;color:#3C5347;display:block}
.doc h4{font-family:var(--serif);font-size:13.5px;margin:14px 0 6px;padding-bottom:3px;border-bottom:1px solid #D8D2C2}
.doc table{width:100%;border-collapse:collapse;font-size:11px}
.doc table th{background:#EFF6F1;border:1px solid #C9DED3;padding:5px 7px;text-align:left;font-size:9.5px;text-transform:uppercase;letter-spacing:.07em}
.doc table td{border:1px solid #DCE8E1;padding:5px 7px}
.doc .sg{display:flex;gap:14px;margin-top:26px}
.doc .sg div{flex:1;border-top:1px solid #12211A;padding-top:5px;font-size:10px;text-align:center}
.doc .fo{margin-top:16px;border-top:1px solid #D8D2C2;padding-top:6px;font-size:9px;color:#6A7C72;display:flex;justify-content:space-between}
.doc .stmp{border:2px solid #9E2C22;color:#9E2C22;font-family:var(--serif);font-size:15px;font-weight:700;padding:5px 14px;transform:rotate(-6deg);display:inline-block;letter-spacing:.08em}
.doc .stmp.ok{border-color:#17794E;color:#17794E}

@media print{
  .side,.mast,.fbar,.btnrow,.filters,.tabs,.back,.stepbar,#toast,.ov,#login{display:none!important}
  .wrap{padding:0;max-width:100%}
  body{background:#fff}
  #prn.on{display:block!important}
  #prn.on ~ .app{display:none!important}
  .doc{max-width:100%}
  @page{size:A4;margin:12mm}
}

/* ═══════════════════════════════════════════════════════════════
   THEME v2.1 — LIGHT · DENSE · FINE-LINED
   Overrides the base kit. Lighter greens, lighter chrome,
   smaller headings, tighter vertical rhythm, clearer marking.
   ═══════════════════════════════════════════════════════════════ */
:root{
  --green:#0C6942; --green-l:#159A63; --green-x:#37B37C;
  --mint:#EDF7F1; --mint-2:#DCEFE4; --mint-3:#BBDFCB;
  --line:#E8E4DA; --line-2:#D9D4C6; --line-g:#EAEFE9;
  --cream:#FBF9F4; --cream-2:#F5F2E9;
  --ink:#17251E; --ink-2:#41564A; --ink-3:#6E8076; --ink-4:#9BA79F;
  --r:9px; --r-s:7px; --r-xs:5px;
  --sh:0 1px 1px rgba(20,40,30,.04),0 1px 4px rgba(20,40,30,.05);
  --sh-2:0 3px 12px rgba(20,40,30,.09);
}
body{font-size:13.4px;line-height:1.48}

/* ---------- masthead: lighter green, shorter ---------- */
.mast{height:52px;background:linear-gradient(100deg,#0C6942 0%,#15855A 52%,#2AA372 100%);
  border-bottom:1px solid #0A5637;box-shadow:0 1px 0 rgba(255,255,255,.16) inset}
.mast .ttl b{font-size:16.5px;letter-spacing:.2em}
.mast .ttl span{font-size:8.6px;letter-spacing:.3em;color:#CBEBDA;margin-top:1px}
.mast .home,.mast .user{background:rgba(255,255,255,.14);border-color:rgba(255,255,255,.26)}
.mast .user .av{width:26px;height:26px;font-size:10.5px}
.mast .user b{font-size:11.8px} .mast .user span{font-size:8.4px;color:#CBEBDA}

/* ---------- sidebar: light, fine-lined ---------- */
.side{width:224px;flex:0 0 224px;background:#FFFFFF;color:var(--ink-2);
  border-right:1px solid var(--line);box-shadow:1px 0 0 rgba(20,40,30,.02)}
.side-h{padding:11px 14px 9px;border-bottom:1px solid var(--line)}
.side-h b{color:var(--ink-3);font-size:9.4px;letter-spacing:.2em}
.side-s{padding:9px 12px 4px}
.side-s input{background:var(--cream-2);border:1px solid var(--line);color:var(--ink);font-size:12px;padding:6px 9px}
.side-s input::placeholder{color:var(--ink-4)}
.ghead{padding:6px 7px;border-radius:7px}
.ghead:hover{background:var(--mint)}
.ghead b{color:var(--ink-2);font-size:10.4px;letter-spacing:.13em;font-weight:800}
.ghead .n{background:var(--cream-2);color:var(--ink-3);border:1px solid var(--line);font-size:9.4px}
.ghead .cv{color:var(--ink-4)}
.ngrp.open .ghead{background:var(--mint);box-shadow:inset 0 0 0 1px var(--mint-3)}
.ngrp.open .ghead b{color:var(--green)}
.gitems{padding:2px 0 5px 18px}
.gitems::before{background:var(--line)}
.side a{display:block;padding:5px 9px;border-radius:6px;color:var(--ink-2);font-size:12.1px;font-weight:640;
  cursor:pointer;text-decoration:none;position:relative;line-height:1.3}
.side a span{display:block;font-size:10.2px;color:var(--ink-4);font-weight:400;margin-top:1px;line-height:1.35}
.side a:hover{background:var(--mint)}
.side a.on{background:var(--mint);color:var(--green);box-shadow:inset 2px 0 0 var(--green)}
.side a.on span{color:var(--ink-3)}
.side a .pill{position:absolute;right:7px;top:6px;background:var(--cream-2);border:1px solid var(--line);
  color:var(--ink-3);border-radius:20px;font-size:9.4px;font-weight:800;padding:0 6px;line-height:15px}
.side a .pill.r{background:var(--crit-bg);border-color:var(--crit-br);color:var(--crit)}
.side-f{border-top:1px solid var(--line);color:var(--ink-4);font-size:9.4px;padding:8px 13px}
.side-h .ic,.ghead .ic{box-shadow:none}

/* ---------- filter bar ---------- */
.fbar{top:52px;background:#fff;border-bottom:1px solid var(--line);padding:7px 16px}
.fchip{padding:3px 9px;font-size:11.6px;border-radius:6px}
.fbar .lb{font-size:9.4px}

/* ---------- page header: compact, one line of copy ---------- */
.ph{padding:11px 15px;margin-bottom:11px;border-left:3px solid var(--green);align-items:center;gap:12px}
.ph h2{font-size:19px;line-height:1.15}
.ph .kicker{font-size:9.2px;letter-spacing:.17em;margin-bottom:1px}
.ph p{font-size:12.1px;margin-top:2px;max-width:none;color:var(--ink-3);
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}

/* ---------- section heading: single line, small ---------- */
.shead{margin:14px 0 8px;gap:8px}
.shead b{font-size:15px}
.shead .sub{font-size:11.4px}
.shead .ltr{width:17px;height:17px;font-size:9.4px;border-radius:5px}
.shead::after{content:"";flex:0 0 0}

/* ---------- cards: light headers, coloured spine ---------- */
.card{margin-bottom:11px;box-shadow:var(--sh)}
.card>header{padding:9px 12px;background:linear-gradient(180deg,#FFFFFF,#FBFAF5);border-bottom:1px solid var(--line)}
.card>header h3{font-size:13.4px}
.card>header .sub{font-size:11.2px}
.card>.body{padding:12px}
.card.acc{border-left:3px solid var(--green)}
.card.acc>header{background:linear-gradient(180deg,#F2FAF5,#E9F5EE);border-bottom-color:var(--mint-3)}
.card.acc>header h3{color:#0A5637} .card.acc>header .sub{color:#4A6B58}
.card.acc-t{border-left:3px solid var(--teal)}
.card.acc-t>header{background:linear-gradient(180deg,#F0FAF8,#E4F4F1);border-bottom-color:#BFE4DD}
.card.acc-t>header h3{color:#0B6155} .card.acc-t>header .sub{color:#4B7C74}
.card.acc-g{border-left:3px solid var(--gold)}
.card.acc-g>header{background:linear-gradient(180deg,#FDF8EA,#F9F0D8)}
.card.acc-g>header h3{color:#7A5F09} .card.acc-g>header .sub{color:#8B7434}
.card.acc-r{border-left:3px solid var(--crit)}
.card.acc-r>header{background:linear-gradient(180deg,#FDF0ED,#F9E3DE)}
.card.acc-r>header h3{color:#8A2419} .card.acc-r>header .sub{color:#9C5348}

/* ---------- tiles: shorter ---------- */
.grid{gap:10px}
.tile{padding:10px 12px;border-left-width:3px}
.tile .v{font-size:22px}
.tile .k{font-size:9.2px;margin-top:4px;letter-spacing:.12em}
.tile .d{font-size:10.6px;margin-top:1px}

/* ---------- tables: green-tinted head, fine rules ---------- */
table.tb{font-size:12.7px}
table.tb th{background:#F2F7F3;color:var(--ink-2);font-size:9.6px;padding:7px 11px;
  border-bottom:1px solid var(--mint-3);letter-spacing:.09em}
table.tb td{padding:7.5px 11px;border-bottom:1px solid var(--line-g)}
table.tb tbody tr:nth-child(even) td{background:#FCFCF9}
table.tb tbody tr.click:hover td{background:var(--mint)}
table.tb tfoot td{background:#F2F7F3;font-weight:800;border-top:1px solid var(--mint-3)}
.tb .nm{font-weight:680}
.sm2{font-size:11px;color:var(--ink-3)}
.empty{padding:26px 14px}
.empty b{font-size:13.4px}

/* ---------- notes / clues ---------- */
.note{padding:9px 11px;font-size:12.1px;line-height:1.5}
.note b{font-size:12.3px;margin-bottom:1px}
.clue{display:flex;gap:9px;align-items:flex-start;background:#F4F9FD;border:1px solid #CFE2F2;
  border-left:3px solid #4B84C4;border-radius:var(--r-s);padding:8px 11px;margin-bottom:10px}
.clue .qm{width:19px;height:19px;flex:0 0 19px;border-radius:50%;background:#4B84C4;color:#fff;
  font-size:11px;font-weight:800;display:grid;place-items:center;margin-top:1px}
.clue .tx{flex:1;font-size:11.9px;color:#2A4E75;line-height:1.5}
.clue .tx b{color:#1E4E86;font-weight:750}
.clue .go{flex:0 0 auto;font-size:11px;font-weight:750;color:#1E4E86;border:1px solid #CFE2F2;background:#fff;
  border-radius:6px;padding:3px 9px;cursor:pointer;white-space:nowrap}
.clue .go:hover{background:#E9F0F9}
.clue.g{background:#F1FAF5;border-color:#C6E6D4;border-left-color:var(--green)}
.clue.g .qm{background:var(--green)} .clue.g .tx{color:#2A5240} .clue.g .tx b{color:#0A5637}
.clue.g .go{color:#0A5637;border-color:#C6E6D4}
.hbtn{display:inline-flex;align-items:center;gap:5px;border:1px solid #CFE2F2;background:#F4F9FD;color:#1E4E86;
  border-radius:6px;padding:2px 9px;font-size:11px;font-weight:750;cursor:pointer;white-space:nowrap}
.hbtn:hover{background:#E4EFFA}
.hbtn i{font-style:normal;font-size:11px}

/* ---------- workflow bar: light ---------- */
.wfb{background:linear-gradient(120deg,#F1FAF5,#E4F3EA);color:var(--ink);border:1px solid var(--mint-3);
  border-left:3px solid var(--green);padding:10px 14px;gap:14px;margin-bottom:11px}
.wfb .lbl{color:var(--ink-3);font-size:9.2px}
.wfb .own{font-size:16px;color:var(--green)}
.wfb .chain i{background:#fff;border:1px solid var(--mint-3);color:var(--ink-3);font-size:10.6px;padding:2px 10px}
.wfb .chain i.dn{background:var(--green);color:#fff;border-color:var(--green)}
.wfb .chain i.cur{background:var(--gold-l);color:#3A2B03;border-color:var(--gold)}
.wfb.rj{background:linear-gradient(120deg,#FDF1EE,#F8E2DD);border-color:var(--crit-br);border-left-color:var(--crit)}
.wfb.rj .own{color:var(--crit)}
.wfb.ok{background:linear-gradient(120deg,#EEF8F1,#DFF1E6);border-color:var(--ok-br);border-left-color:var(--ok)}
.wfb.ok .own{color:var(--ok)}
.wfb.qy{background:linear-gradient(120deg,#FDF6E4,#F8EDD3);border-color:var(--gold-br);border-left-color:var(--gold)}
.wfb.qy .own{color:#7A5F09}

/* ---------- before / after marking ---------- */
.dif{font-size:12.4px}
.dif th{background:#F2F7F3;border-bottom-color:var(--mint-3);font-size:9.6px;padding:7px 9px;color:var(--ink-2)}
.dif td{padding:7px 9px}
.dif td.was{color:#9E2C22;text-decoration:line-through;background:#FDF3F1}
.dif td.now{color:#0A5637;font-weight:750;background:#EFF8F2}
.dif td.rec{color:var(--sp);background:#F5F1FC;font-weight:750}
.dif td.fin{color:#3A2B03;background:#FBF3DC;font-weight:800}
.dif tr:nth-child(even) td{background:transparent}
.dif tr:nth-child(even) td.was{background:#FDF3F1}
.dif tr:nth-child(even) td.now{background:#EFF8F2}
.dif tr:nth-child(even) td.fin{background:#FBF3DC}
.ba{display:grid;grid-template-columns:1fr auto 1fr;gap:0;border:1px solid var(--line);border-radius:var(--r);overflow:hidden;background:#fff}
.ba>.col{min-width:0}
.ba>.col>h5{margin:0;padding:8px 12px;font-size:9.8px;letter-spacing:.14em;text-transform:uppercase;font-weight:800;
  border-bottom:1px solid var(--line)}
.ba>.col.b>h5{background:#FDF3F1;color:#8A2419;border-bottom-color:#F0D5CF}
.ba>.col.a>h5{background:#EFF8F2;color:#0A5637;border-bottom-color:var(--mint-3)}
.ba>.mid{width:34px;background:var(--cream-2);border-left:1px solid var(--line);border-right:1px solid var(--line);
  display:flex;flex-direction:column;align-items:center;padding-top:34px;gap:0}
.ba .rw{display:flex;justify-content:space-between;gap:10px;padding:6.5px 12px;border-bottom:1px solid var(--line-g);
  font-size:12.2px;min-height:31px;align-items:center}
.ba .rw:last-child{border-bottom:0}
.ba .rw .lb{color:var(--ink-3);font-size:11.2px}
.ba .rw .vl{font-weight:700;text-align:right}
.ba .rw.hit{background:#FFFBEF;box-shadow:inset 3px 0 0 var(--gold)}
.ba .col.b .rw.hit .vl{color:#9E2C22}
.ba .col.a .rw.hit .vl{color:#0A5637}
.ba .mid .ar{height:31px;display:grid;place-items:center;font-size:11px;color:var(--ink-4);width:100%}
.ba .mid .ar.hit{color:var(--gold);font-weight:800;background:#FFFBEF}
.mk{display:inline-flex;align-items:center;gap:4px;border-radius:5px;padding:0 6px;font-size:10px;font-weight:800;
  letter-spacing:.04em;line-height:16px;border:1px solid}
.mk.b{background:#FDF3F1;border-color:#F0D5CF;color:#8A2419}
.mk.a{background:#EFF8F2;border-color:var(--mint-3);color:#0A5637}
.mk.c{background:#FBF3DC;border-color:var(--gold-br);color:#7A5F09}

/* ---------- misc density ---------- */
.kv{padding:5px 0;font-size:12.3px}
.stepbar{margin-bottom:11px}
.stepbar div{padding:7px 10px;font-size:11.6px}
.stepbar div.on{background:linear-gradient(160deg,#159A63,#0C6942)}
.stepbar div b{font-size:9.2px}
.chip{padding:2px 9px;font-size:11px}
.chip.on{background:linear-gradient(160deg,#159A63,#0C6942)}
.tag{font-size:10.2px;line-height:17px;padding:0 8px}
.dcard>header{padding:10px 12px;background:linear-gradient(180deg,#F2FAF5,#E7F4EC);color:var(--ink);border-bottom-color:var(--mint-3)}
.dcard>header h3{font-size:14px;color:#0A5637}
.dcard>header .sub{color:var(--ink-3);font-size:9.4px}
.dcard.sel>header{background:linear-gradient(180deg,#FDF8EA,#F7EDD5)}
.dcard.sel>header h3{color:#7A5F09}
.dcard .exp{font-size:11.7px;margin-bottom:7px}
.dcard .dbody{padding:10px 11px}
.opt{padding:6px 8px;margin-bottom:5px;background:#fff}
.opt b{font-size:12.2px} .opt span{font-size:10.7px}
.dfoot{padding:7px 11px;font-size:10.4px}
.guide .row{
  padding:8px 12px!important;
  margin-left:0!important;
  margin-right:0!important
}
.guide .row b{font-size:12.3px} .guide .row span{font-size:11.6px}
.btn{padding:5px 12px;font-size:12.2px}
.btn.lg{padding:8px 16px;font-size:13px}
.btn.sm{padding:2px 9px;font-size:11px}
.filters{padding:9px 11px;gap:10px}
.fl label{font-size:9.2px}
.prog .cnt{font-size:12.2px}
.prog .nx{font-size:10.2px}


/* ═══════════════════════════════════════════════════════════════
   THEME v2.2 — one size up · readable nav · premium striping
   ═══════════════════════════════════════════════════════════════ */
body{font-size:14.6px;line-height:1.5}

/* ---------- sidebar: legible on light ---------- */
.side{width:246px;flex:0 0 246px}
.side .nav a{display:block;position:relative;padding:7px 10px 7px 14px;border-radius:7px;
  color:var(--ink-2);font-size:13.2px;font-weight:640;line-height:1.32;text-decoration:none;cursor:pointer;
  transition:background .12s,color .12s}
.side .nav a::before{content:"";position:absolute;left:-15px;top:13px;width:7px;height:7px;border-radius:50%;
  background:#fff;border:1.5px solid var(--mint-3);box-shadow:none}
.side .nav a span{display:block;font-size:11.1px;color:var(--ink-4);font-weight:400;margin-top:1px;line-height:1.35}
.side .nav a:hover{background:var(--mint);color:var(--green)}
.side .nav a:hover span{color:var(--ink-3)}
.side .nav a.on{background:linear-gradient(90deg,#E6F5EC,#F3FBF6);color:#0A5637;font-weight:750;
  box-shadow:inset 2px 0 0 var(--green)}
.side .nav a.on span{color:#4A6B58}
.side .nav a.on::before{background:var(--gold);border-color:#F0DCA4;box-shadow:0 0 0 3px rgba(184,144,31,.16)}
.side .nav a .pill{position:absolute;right:8px;top:8px;background:var(--cream-2);border:1px solid var(--line);
  color:var(--ink-3);border-radius:20px;padding:0 7px;font-size:10px;font-weight:800;line-height:16px}
.side .nav a .pill.r{background:var(--crit-bg);border-color:var(--crit-br);color:var(--crit)}
.ghead b{font-size:11.2px}
.ghead .n{font-size:10px}
.side-h b{font-size:10.2px}
.side-s input{font-size:12.8px;padding:7px 10px}
.side-f{font-size:10.2px}
.gitems::before{background:var(--line)}

/* ---------- masthead / bars a touch larger ---------- */
.mast{height:56px}
.mast .ttl b{font-size:18px}
.mast .ttl span{font-size:9.2px}
.mast .user b{font-size:12.8px}
.fbar{top:56px;padding:8px 18px}
.fchip{font-size:12.6px;padding:4px 10px}
.fbar .lb{font-size:10.2px}
.app{min-height:calc(100vh - 56px)}
.side{position:sticky;top:56px;height:calc(100vh - 56px)}

/* ---------- headings ---------- */
.ph{padding:13px 17px}
.ph h2{font-size:21.5px}
.ph .kicker{font-size:10px}
.ph p{font-size:13.1px}
.shead b{font-size:16.5px}
.shead .sub{font-size:12.3px}
.shead .ltr{width:19px;height:19px;font-size:10.2px}
.card>header h3{font-size:14.6px}
.card>header .sub{font-size:12.1px}
.tile .v{font-size:24px}
.tile .k{font-size:10px}
.tile .d{font-size:11.6px}

/* ---------- tables: sticky head, clear zebra, hover lift ---------- */
table.tb{font-size:13.7px}
table.tb th{position:sticky;top:0;z-index:2;font-size:10.4px;padding:9px 13px;
  background:linear-gradient(180deg,#F4F9F5,#EBF4EE);border-bottom:1px solid var(--mint-3);
  box-shadow:0 1px 0 rgba(20,60,40,.04)}
table.tb td{padding:9px 13px;border-bottom:1px solid #EFEDE4}
table.tb tbody tr:nth-child(odd) td{background:#FFFFFF}
table.tb tbody tr:nth-child(even) td{background:#F8FAF7}
table.tb tbody tr.click{cursor:pointer;transition:background .1s}
table.tb tbody tr.click:hover td{background:#EAF6EF;box-shadow:inset 0 1px 0 var(--mint-3),inset 0 -1px 0 var(--mint-3)}
table.tb tbody tr.click:hover td:first-child{box-shadow:inset 3px 0 0 var(--green),inset 0 1px 0 var(--mint-3),inset 0 -1px 0 var(--mint-3)}
table.tb tbody tr.held td{background:#FDF7E9!important}
table.tb tbody tr.held:hover td{background:#FBF1DA!important}
.sm2{font-size:11.9px}
.tb .nm{font-weight:700;font-size:13.7px}
.mono{font-size:12.6px}
.dif{font-size:13.3px}
.dif th{font-size:10.4px;padding:8px 11px}
.dif td{padding:8px 11px}
.kv{font-size:13.2px;padding:6px 0}
.note{font-size:13px;padding:10px 12px}
.note b{font-size:13.2px}
.clue .tx{font-size:12.8px}
.clue .go,.hbtn{font-size:11.8px;padding:4px 11px}
.tag{font-size:10.8px;line-height:18px;padding:0 9px}
.chip{font-size:11.8px;padding:3px 10px}
.btn{font-size:13.2px;padding:6px 13px}
.btn.sm{font-size:11.8px;padding:3px 10px}
.btn.big{padding:9px 19px;font-size:14.4px;font-weight:700}
.empty b{font-size:15px}
.prog .cnt{font-size:13.2px}
.prog .nx{font-size:11px}
.opt b{font-size:13.1px}
.opt span{font-size:11.6px}
.dcard>header h3{font-size:15px}
.dcard .exp{font-size:12.6px}
.guide .row b{font-size:13.2px}
.guide .row span{font-size:12.5px}
.ba .rw{font-size:13.1px;padding:7px 13px;min-height:34px}
.ba .rw .lb{font-size:12.1px}
.ba .mid .ar{height:34px}
.ba>.col>h5{font-size:10.4px;padding:9px 13px}
.mk{font-size:10.6px;line-height:17px}
.fl label{font-size:10px}
.filters input,.filters select{font-size:13.2px}
.tabs a{font-size:13px}
.wfb .own{font-size:17.5px}
.modal>header h3{font-size:17.5px}
.modal>header{background:linear-gradient(110deg,#0C6942,#15855A 60%,#2AA372)}
.tline .hd{font-size:13.4px}
.tline .mt{font-size:11.6px}
.tline .bd{font-size:12.8px}

/* ---------- premium finish ---------- */
.card{border-radius:11px;box-shadow:0 1px 2px rgba(20,45,32,.05),0 6px 18px -10px rgba(20,45,32,.18)}
.card:hover{box-shadow:0 1px 2px rgba(20,45,32,.06),0 10px 26px -12px rgba(20,45,32,.24)}
.tile{border-radius:10px;background:linear-gradient(180deg,#FFFFFF,#FCFCF8);
  box-shadow:0 1px 2px rgba(20,45,32,.05),0 5px 14px -9px rgba(20,45,32,.2)}
.tile:hover{transform:translateY(-2px);box-shadow:0 2px 4px rgba(20,45,32,.07),0 12px 26px -12px rgba(20,45,32,.28)}
.ph{border-radius:11px;background:linear-gradient(115deg,#FFFFFF 55%,#FBFCFA)}
.clue{border-radius:9px}
.btn{border-radius:7px}
.btn.p{background:linear-gradient(160deg,#159A63,#0C6942)}
.btn.p:hover{background:linear-gradient(160deg,#18AC6F,#0E7A4C)}
.tabs{border-bottom:1px solid var(--line)}
.tabs a.on{box-shadow:inset 0 -2px 0 var(--green)}

/* ═══════════════════════════════════════════════════════════════
   THEME v3.0 — sections, zoom, tips, report, responsive
   ═══════════════════════════════════════════════════════════════ */
.main{zoom:1}
body.z1 .main{zoom:.90} body.z2 .main{zoom:1} body.z3 .main{zoom:1.10} body.z4 .main{zoom:1.22}
.zoomer{display:inline-flex;align-items:center;border:1px solid var(--line-2);border-radius:7px;overflow:hidden;background:#fff}
.zoomer b{font-size:9.6px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3);padding:0 8px;font-weight:800}
.zoomer i{font-style:normal;cursor:pointer;padding:4px 9px;border-left:1px solid var(--line);font-weight:800;color:var(--ink-2);line-height:1}
.zoomer i:hover{background:var(--mint);color:var(--green)}
.zoomer i.on{background:linear-gradient(160deg,#159A63,#0C6942);color:#fff}
.zoomer i.a1{font-size:10px} .zoomer i.a2{font-size:12px} .zoomer i.a3{font-size:14px} .zoomer i.a4{font-size:16px}

/* ---------- section rail ---------- */
.srail{display:flex;align-items:center;gap:8px;flex-wrap:wrap;background:#fff;border:1px solid var(--line);
  border-radius:9px;padding:6px 9px;margin-bottom:11px;box-shadow:var(--sh)}
.srail .nv{border:1px solid var(--line-2);background:#fff;border-radius:6px;padding:3px 10px;font-size:12px;
  font-weight:700;cursor:pointer;color:var(--ink-2);white-space:nowrap}
.srail .nv:hover{background:var(--mint);border-color:var(--mint-3);color:var(--green)}
.srail .nv:disabled{opacity:.4;cursor:not-allowed}
.srail .pos{font-size:11.4px;color:var(--ink-3);white-space:nowrap}
.srail .pos b{color:var(--ink);font-weight:750}
.srail .dots{display:flex;gap:4px;flex:1;min-width:60px}
.srail .dots i{width:16px;height:5px;border-radius:3px;background:var(--line-2);cursor:pointer;display:block}
.srail .dots i.on{background:linear-gradient(90deg,#159A63,#37B37C)}
.srail .dots i.cl{background:var(--gold-l)}

/* ---------- collapsible sections ---------- */
.shead{cursor:pointer;user-select:none;border-radius:7px;padding:3px 5px;margin-left:-5px}
.shead:hover{background:#F2F7F3}
.shead .cv{transition:transform .16s;display:inline-block}
.shead.cl .cv{transform:rotate(-90deg)}
.shead.cl{background:#FBF9F2}
.ssec{overflow:hidden}
.ssec.cl{display:none}
.bulb{border:1px solid var(--gold-br);background:var(--gold-bg);color:#7A5F09;border-radius:6px;
  padding:2px 8px;font-size:11.4px;font-weight:750;cursor:pointer;white-space:nowrap;line-height:17px}
.bulb:hover{background:#F7EBCB}
.bulb.on{background:linear-gradient(160deg,#D9B54A,#B8901F);color:#3A2B03;border-color:#A87C12}
.tipbox{background:#FFFCF2;border:1px solid var(--gold-br);border-left:3px solid var(--gold);border-radius:8px;
  padding:9px 12px;margin:-4px 0 10px;font-size:12.4px;color:#5C4A12;line-height:1.55;display:flex;gap:9px}
.tipbox .bi{font-size:15px;line-height:1.2}
.tipbox b{color:#7A5F09}

/* ---------- mandatory field walker ---------- */
input.miss,select.miss,textarea.miss{border-color:#E38A7E!important;background:#FEF6F4!important;
  box-shadow:0 0 0 3px rgba(227,138,126,.18)!important}
.reqmsg{display:flex;align-items:center;gap:8px;background:#FDF2EF;border:1px solid #F0CFC8;border-left:3px solid #C4574A;
  border-radius:8px;padding:8px 11px;margin:9px 0;font-size:12.4px;color:#8A2419;font-weight:640}
.reqmsg .n{background:#C4574A;color:#fff;border-radius:20px;font-size:10px;font-weight:800;padding:1px 8px}
label .rq{color:#C4574A;font-weight:800;font-size:10.5px;letter-spacing:.04em}
.fg.need label{color:#8A2419}

/* ---------- report system ---------- */
.rtool{display:flex;gap:8px;flex-wrap:wrap;align-items:center;background:#fff;border:1px solid var(--line);
  border-radius:9px;padding:8px 10px;margin-bottom:10px;box-shadow:var(--sh)}
.rtool .grow{flex:1;min-width:120px}
.colmenu{position:relative;display:inline-block}
.colpop{position:absolute;right:0;top:calc(100% + 6px);z-index:90;background:#fff;border:1px solid var(--line-2);
  border-radius:9px;box-shadow:var(--sh-2);padding:9px;min-width:250px;max-height:330px;overflow:auto;display:none}
.colpop.on{display:block}
.colpop h6{margin:0 0 7px;font-size:9.6px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3);font-weight:800}
.colpop label{display:flex;align-items:center;gap:8px;padding:4px 5px;border-radius:6px;font-size:12.4px;cursor:pointer}
.colpop label:hover{background:var(--mint)}
.colpop .ft{display:flex;gap:6px;margin-top:8px;border-top:1px solid var(--line);padding-top:8px}
table.tb th.hid,table.tb td.hid{display:none}
.rsum{display:flex;gap:16px;flex-wrap:wrap;background:linear-gradient(180deg,#F4F9F5,#EBF4EE);border:1px solid var(--mint-3);
  border-radius:9px;padding:9px 13px;margin-bottom:10px}
.rsum div{min-width:110px}
.rsum .k{font-size:9.4px;letter-spacing:.13em;text-transform:uppercase;color:var(--ink-3);font-weight:800}
.rsum .v{font-family:var(--serif);font-size:18px;font-weight:650;color:var(--green);margin-top:1px}

/* ---------- responsive ---------- */
@media(max-width:1200px){.grid.g7,.grid.g6{grid-template-columns:repeat(3,1fr)}.grid.g5,.grid.g4{grid-template-columns:repeat(2,1fr)}}
@media(max-width:980px){
  .side{position:fixed;left:0;top:56px;bottom:0;z-index:150;transform:translateX(-104%);transition:transform .2s;
    box-shadow:var(--sh-3);height:auto}
  .side.show{transform:none}
  .grid.g7,.grid.g6,.grid.g5,.grid.g4,.grid.g3,.grid.g2,.grid.g-21{grid-template-columns:repeat(2,1fr)}
  .ph{flex-direction:column;align-items:flex-start}
  .ba{grid-template-columns:1fr}.ba>.mid{display:none}
  .ba>.col.b{border-bottom:2px solid var(--line-2)}
}
@media(max-width:640px){
  .grid.g7,.grid.g6,.grid.g5,.grid.g4,.grid.g3,.grid.g2,.grid.g-21{grid-template-columns:1fr}
  .ph h2{font-size:18px}.mast .ttl b{font-size:14px}
  .srail .dots{display:none}
  .fbar{padding:6px 10px;gap:6px}
  .modal>.body{padding:12px;max-height:calc(100vh - 150px)}
  .stepbar div{min-width:100%}
}
@media print{
  .srail,.bulb,.tipbox,.rtool,.zoomer,.clue,.hbtn{display:none!important}
  .ssec.cl{display:block!important}
  table.tb th.hid,table.tb td.hid{display:none!important}
}

/* ═══════════════════════════════════════════════════════════════
   THEME v3.1 — typographic hierarchy, journey tracker, badges
   ═══════════════════════════════════════════════════════════════ */
/* ---------- quick guide: light yellow, maroon text ---------- */
.clue{background:linear-gradient(180deg,#FFFDF2,#FDF6DC);border:1px solid #EBDCA6;border-left:4px solid #8A2419}
.clue .qm{background:linear-gradient(155deg,#A8392A,#6E1C12);color:#FFF4E8}
.clue .tx{color:#7A2E1E} .clue .tx b{color:#6E1C12;font-weight:800}
.clue .go{color:#6E1C12;border-color:#EBDCA6;background:#fff}
.clue .go:hover{background:#FBF1D4}
.clue.g{background:linear-gradient(180deg,#FFFDF2,#FBF2D8);border-color:#EBDCA6;border-left-color:#8A2419}
.clue.g .qm{background:linear-gradient(155deg,#A8392A,#6E1C12)}
.clue.g .tx{color:#7A2E1E} .clue.g .tx b{color:#6E1C12}
.clue.g .go{color:#6E1C12;border-color:#EBDCA6}

/* ---------- typography hierarchy ---------- */
.ph h2{font-family:var(--serif);font-size:24px;font-weight:660;letter-spacing:-.012em;line-height:1.1;color:#0B2B1C}
.ph .kicker{font-size:9.6px;letter-spacing:.24em;font-weight:800;color:#96742A}
.ph p{font-size:13.4px;color:var(--ink-2);line-height:1.5;font-weight:450}
.shead{margin:18px 0 9px;padding-bottom:5px;border-bottom:1px solid var(--line);align-items:baseline}
.shead b{font-family:var(--serif);font-size:18px;font-weight:650;letter-spacing:-.008em;color:#0B2B1C}
.shead .sub{font-size:11.6px;letter-spacing:.02em;color:var(--ink-3);font-style:italic}
.shead .ltr{background:linear-gradient(160deg,#F3E4B4,#DCC173);border-color:#C8A94C;color:#4A3705;
  width:20px;height:20px;font-size:10px;font-weight:800;align-self:center}
.card>header h3{font-family:var(--serif);font-size:15.4px;font-weight:640;letter-spacing:-.005em}
.card>header .sub{font-size:11.2px;letter-spacing:.05em;text-transform:uppercase;font-weight:700;color:var(--ink-3)}
.tile .v{font-family:var(--serif);letter-spacing:-.02em}
.tile .k{font-weight:800;letter-spacing:.14em;color:var(--ink-2)}
.dcard>header h3{font-size:16px;letter-spacing:-.008em}
.dcard>header .sub{letter-spacing:.16em;font-weight:800;font-size:9.2px}
.note b{font-family:var(--serif);font-size:13.4px;font-weight:640}
h2,h3{font-feature-settings:"liga" 1,"kern" 1}

/* ---------- top bar actions ---------- */
.fbar .tbtn{display:inline-flex;align-items:center;gap:7px;border-radius:7px;padding:5px 13px;font-size:12.8px;
  font-weight:720;cursor:pointer;border:1px solid;white-space:nowrap;transition:.13s}
.fbar .tbtn.new{background:linear-gradient(160deg,#159A63,#0C6942);border-color:#0A5637;color:#fff;
  box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 2px 8px -3px rgba(12,105,66,.6)}
.fbar .tbtn.new:hover{filter:brightness(1.09)}
.fbar .tbtn.q{background:#fff;border-color:var(--line-2);color:var(--ink)}
.fbar .tbtn.q:hover{background:var(--mint);border-color:var(--mint-3)}
.cbadge{display:inline-grid;place-items:center;min-width:21px;height:21px;padding:0 7px;border-radius:20px;
  font-size:11.4px;font-weight:800;font-family:var(--serif);letter-spacing:0;
  background:linear-gradient(160deg,#E8604E,#A8281A);color:#fff;
  box-shadow:0 1px 0 rgba(255,255,255,.25) inset,0 2px 7px -2px rgba(168,40,26,.8)}
.cbadge.z{background:linear-gradient(160deg,#DCEFE4,#BBDFCB);color:#2A5240;box-shadow:none}
.cbadge.g{background:linear-gradient(160deg,#D9B54A,#A87C12);color:#3A2B03}
@keyframes pulseb{0%,100%{box-shadow:0 0 0 0 rgba(168,40,26,.5)}50%{box-shadow:0 0 0 6px rgba(168,40,26,0)}}
.cbadge.live{animation:pulseb 1.9s infinite}
.side a .pill{min-width:20px;height:19px;padding:0 7px;border-radius:20px;font-size:10.6px;font-weight:800;
  background:linear-gradient(160deg,#DCEFE4,#BBDFCB);color:#2A5240;border:0;display:grid;place-items:center;line-height:1}
.side a .pill.r{background:linear-gradient(160deg,#E8604E,#A8281A);color:#fff;animation:pulseb 2.2s infinite}

/* ---------- journey tracker ---------- */
.jrny{background:linear-gradient(120deg,#FFFFFF,#F7FBF8);border:1px solid var(--line);border-left:4px solid var(--green);
  border-radius:11px;padding:11px 13px;margin-bottom:12px;box-shadow:var(--sh)}
.jrny .hd{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:9px}
.jrny .hd b{font-family:var(--serif);font-size:15px;color:#0B2B1C}
.jrny .hd .now{background:linear-gradient(160deg,#159A63,#0C6942);color:#fff;border-radius:20px;
  padding:2px 11px;font-size:11.2px;font-weight:750}
.jrny .hd .nxt{background:var(--gold-bg);border:1px solid var(--gold-br);color:#7A5F09;border-radius:20px;
  padding:1px 10px;font-size:11.2px;font-weight:750}
.jr{display:flex;align-items:flex-start;gap:0;overflow-x:auto;padding-bottom:3px}
.jr .n{flex:1;min-width:104px;text-align:center;position:relative;padding:0 4px}
.jr .n::before{content:"";position:absolute;left:-50%;top:15px;width:100%;height:2px;background:var(--line-2)}
.jr .n:first-child::before{display:none}
.jr .n.dn::before,.jr .n.cur::before{background:linear-gradient(90deg,#2FA46F,#12764C)}
.jr .n i{position:relative;z-index:2;display:grid;place-items:center;width:31px;height:31px;margin:0 auto 5px;
  border-radius:50%;background:#fff;border:2px solid var(--line-2);font-style:normal;font-size:13px;color:var(--ink-4);font-weight:800}
.jr .n.dn i{background:linear-gradient(160deg,#2FA46F,#0C6942);border-color:#0A5637;color:#fff}
.jr .n.cur i{background:linear-gradient(160deg,#F0C864,#B8901F);border-color:#8C6A0E;color:#3A2B03;
  box-shadow:0 0 0 4px rgba(184,144,31,.18);animation:pulseg 2s infinite}
@keyframes pulseg{0%,100%{box-shadow:0 0 0 4px rgba(184,144,31,.18)}50%{box-shadow:0 0 0 9px rgba(184,144,31,0)}}
.jr .n.rj i{background:linear-gradient(160deg,#D4685A,#8A2419);border-color:#7A1D13;color:#fff}
.jr .n b{display:block;font-size:11.6px;font-weight:740;color:var(--ink-2);line-height:1.25}
.jr .n span{display:block;font-size:10.2px;color:var(--ink-4);margin-top:1px;line-height:1.3}
.jr .n.cur b{color:#7A5F09} .jr .n.dn b{color:#0A5637}

/* ---------- step 1 shine ---------- */
.stepbar div.on{position:relative;overflow:hidden;
  box-shadow:0 3px 14px -5px rgba(12,105,66,.75),0 0 0 1px #0A5637 inset}
.stepbar div.on::after{content:"";position:absolute;top:0;left:-60%;width:45%;height:100%;
  background:linear-gradient(100deg,rgba(255,255,255,0),rgba(255,255,255,.34),rgba(255,255,255,0));
  animation:shine 2.6s infinite}
@keyframes shine{0%{left:-60%}55%{left:120%}100%{left:120%}}
.stepbar div.dn{background:linear-gradient(160deg,#E8F5EE,#D7EDE1);color:#0A5637;box-shadow:inset 0 0 0 1px var(--mint-3)}

/* ---------- multi-select field picker ---------- */
.opt .ck{width:17px;height:17px;flex:0 0 17px;border-radius:5px;border:2px solid var(--ink-4);margin-top:2px;
  display:grid;place-items:center;background:#fff;font-size:11px;color:transparent;font-weight:900}
.opt.on .ck{border-color:var(--gold);background:linear-gradient(160deg,#D9B54A,#B8901F);color:#3A2B03}
.dcard.dim{opacity:.5}
.dcard.dim .opt{pointer-events:none}
.dcard .cnt{margin-left:auto}
.selbar{position:sticky;bottom:0;z-index:70;background:linear-gradient(180deg,rgba(255,255,255,.9),#fff);
  border:1px solid var(--mint-3);border-radius:11px;padding:10px 13px;margin-top:12px;display:flex;
  align-items:center;gap:11px;flex-wrap:wrap;box-shadow:0 -3px 16px -8px rgba(20,45,32,.4)}
.selbar .lb{font-size:12.6px;color:var(--ink-2)}
.selbar .lb b{font-family:var(--serif);font-size:16px;color:var(--green)}
.selchip{display:inline-flex;align-items:center;gap:6px;background:var(--gold-bg);border:1px solid var(--gold-br);
  color:#5C4A12;border-radius:20px;padding:2px 10px;font-size:11.6px;font-weight:700;margin:2px 5px 2px 0}
.selchip x{cursor:pointer;font-weight:900;color:#8A2419;font-style:normal}

/* ---------- bulk approval ---------- */
.bulkbar{position:sticky;top:104px;z-index:65;background:linear-gradient(120deg,#F1FAF5,#E2F2E9);
  border:1px solid var(--mint-3);border-left:4px solid var(--green);border-radius:10px;padding:9px 13px;
  margin-bottom:11px;display:flex;align-items:center;gap:11px;flex-wrap:wrap}
.bulkbar .lb{font-size:12.8px;color:var(--ink-2)}
.bulkbar .lb b{font-family:var(--serif);font-size:17px;color:var(--green)}
.qck{width:19px;height:19px;border-radius:5px;border:2px solid var(--ink-4);background:#fff;display:grid;
  place-items:center;cursor:pointer;font-size:12px;font-weight:900;color:transparent}
.qck.on{border-color:var(--green);background:linear-gradient(160deg,#2FA46F,#0C6942);color:#fff}
.card.picked{box-shadow:0 0 0 2px var(--green),var(--sh-2)}

/* ERPNext website chrome hidden */
.navbar{display:none!important;}
.web-footer{display:none!important;}

/* ============================================================
   ERPNext LIVE WEB PAGE OVERRIDES
   ============================================================ */
.navbar{display:none!important}
.web-footer{display:none!important}

html,body{margin:0!important;padding:0!important}
body{overflow-x:hidden}
#life-dcr-root{width:100%;min-height:100vh;margin:0;padding:0;background:var(--cream);color:var(--ink)}
#life-dcr-root button{font-family:inherit}
#life-dcr-root .mast{top:0}
#life-dcr-root .side{top:52px;height:calc(100vh - 52px)}
#life-dcr-root .fbar{top:52px}

/* Frappe website wrappers should not constrain this app */
.web-page-content,.page-content-wrapper,.page_content,.page-content,.main-column,
.container.my-4,.container-fluid.my-4{max-width:none!important;width:100%!important;margin:0!important;padding:0!important}

.life-xbtn{border:0;background:transparent;color:#fff}
.life-hidden{display:none!important}
.life-click{cursor:pointer}
.life-muted{color:var(--ink-3)}
.life-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}
.life-toolbar{display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap;margin-bottom:12px}
.life-toolbar .fl{min-width:150px}
.life-toolbar .grow{flex:1;min-width:220px}
.life-kvgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 24px}
.life-source-results{max-height:360px;overflow:auto;border:1px solid var(--line);border-radius:8px;background:#fff}
.life-source-row{padding:10px 12px;border-bottom:1px solid var(--line-g);cursor:pointer;display:flex;gap:12px;align-items:center}
.life-source-row:last-child{border-bottom:0}
.life-source-row:hover{background:var(--mint)}
.life-source-row.on{background:var(--gold-bg);box-shadow:inset 3px 0 0 var(--gold)}
.life-source-row .mainx{flex:1;min-width:0}
.life-source-row .nm{font-weight:700;word-break:break-word}
.life-source-row .meta{font-size:11px;color:var(--ink-3);margin-top:2px}
.life-file-line{display:flex;align-items:center;gap:8px;margin-top:5px;font-size:11px;color:var(--ink-3)}
