.life-loading{display:inline-flex;align-items:center;gap:7px;color:var(--ink-3);font-size:12px}
.life-spinner{width:14px;height:14px;border:2px solid var(--line-2);border-top-color:var(--green);border-radius:50%;animation:lifeSpin .7s linear infinite}
@keyframes lifeSpin{to{transform:rotate(360deg)}}
.life-pagination{display:flex;justify-content:flex-end;gap:6px;align-items:center;padding:10px 12px;border-top:1px solid var(--line);background:#fff}
.life-pagination .pg{min-width:30px;height:30px;border:1px solid var(--line-2);border-radius:6px;background:#fff;cursor:pointer;font-size:11px;font-weight:700}
.life-pagination .pg.on{background:var(--green);border-color:var(--green);color:#fff}
.life-pagination .pg:disabled{opacity:.4;cursor:not-allowed}
.life-statusline{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.life-request-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;flex-wrap:wrap}
.life-request-head .id{font-family:var(--mono);font-weight:800;color:var(--green)}
.life-diff{width:100%;border-collapse:collapse}
.life-diff th,.life-diff td{padding:8px 10px;border-bottom:1px solid var(--line-g);text-align:left;vertical-align:top}
.life-diff th{font-size:10px;text-transform:uppercase;letter-spacing:.08em;background:#f3f7f4;color:var(--ink-2)}
.life-diff .old{color:var(--ink-3)}
.life-diff .req{font-weight:750;color:var(--green)}
.life-diff .final{font-weight:750;color:#6e5407;background:var(--gold-bg)}
.life-approval-item{padding:9px 0;border-bottom:1px solid var(--line-g)}
.life-approval-item:last-child{border-bottom:0}
.life-approval-item .top{display:flex;justify-content:space-between;gap:8px;align-items:center}
.life-approval-item .meta{font-size:11px;color:var(--ink-3);margin-top:2px}
.life-access-denied{max-width:720px;margin:70px auto;padding:0 20px}
.life-access-denied .card{border-left:4px solid var(--crit)}
.life-compact td,.life-compact th{white-space:nowrap}

@media(max-width:880px){
  .life-kvgrid{grid-template-columns:1fr}
  .life-toolbar .fl,.life-toolbar .grow{width:100%;min-width:0}
  #top-new{display:none}
}


/* ============================================================
   SIDEBAR GROUP ALIGNMENT FIX
   Keep title on the left, count + chevron aligned on the right.
   ============================================================ */

#life-dcr-root #life-dcr-side .ghead{
  display:flex!important;
  align-items:center!important;
  width:100%!important;
  gap:10px!important;
  padding-left:10px!important;
  padding-right:10px!important;
  box-sizing:border-box!important;
}

#life-dcr-root #life-dcr-side .ghead>b{
  flex:0 1 auto!important;
  min-width:0!important;
  margin:0!important;
}

#life-dcr-root #life-dcr-side .ghead>.n{
  margin-left:auto!important;
