javascript:
'use strict';

/* ============================================================
   LIFE ERP · DATA CORRECTION REQUEST & APPROVALS · LIVE
   Frontend for Server Script API: life_data_correction_api
   No sample users. No sample records. No simulated login.
   ============================================================ */

window.lifeDCR = (function(){
  var API = 'life_data_correction_api';
  var S = {
    ready:false, context:null, rules:[], dashboard:{}, allRequests:[], requests:[], approvals:[], decisionSaving:{},
    currentRequest:null, currentCanAct:false, pendingApprovedChanges:[],
    route:'dash', openGroup:'COMMAND', branch:'', status:'', search:'', page:1, pageSize:20,
    sourceRows:[], selectedRule:'', selectedSource:'', selectedSourceData:null,
    uploaded:['','','']
  };

  function byId(id){ return document.getElementById(id); }
  function esc(v){
    return String(v==null?'':v)
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
      .replace(/"/g,'&quot;').replace(/'/g,'&#039;');
  }
  function attr(v){ return esc(v).replace(/`/g,'&#096;'); }
  function clean(v){ return String(v==null?'':v).trim(); }
  function ini(name){
    var p=clean(name).split(/\s+/).filter(Boolean);
    if(!p.length)return '--';
    if(p.length===1)return p[0].slice(0,2).toUpperCase();
    return (p[0][0]+p[p.length-1][0]).toUpperCase();
  }
  function pad(n){ return n<10?'0'+n:String(n); }
  var MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  function fmtD(v){
    if(!v)return '—';
    var d=String(v).split(' ')[0].split('-');
    if(d.length!==3)return String(v);
    return d[2]+'-'+MON[(+d[1])-1]+'-'+String(d[0]).slice(-2);
  }
  function fmtDT(v){
    if(!v)return '—';
    var raw=String(v).replace('T',' '), a=raw.split(' '), date=fmtD(a[0]);
    if(!a[1])return date;
    var p=a[1].split(':'), hh=parseInt(p[0]||'0',10), mm=pad(parseInt(p[1]||'0',10));
    var ap=hh>=12?'pm':'am'; hh=hh%12||12;
    return date+' · '+hh+':'+mm+' '+ap;
  }

  function todayText(){
    var d=new Date();
    return pad(d.getDate())+'-'+MON[d.getMonth()]+'-'+String(d.getFullYear()).slice(-2);
  }
  function toast(msg, cls){
    var host=byId('toast'); if(!host)return;
    var d=document.createElement('div'); d.className='tst '+(cls||''); d.textContent=msg;
    host.appendChild(d);
    setTimeout(function(){ d.style.opacity='0'; d.style.transition='.3s'; setTimeout(function(){d.remove();},320); },3000);
  }
  function tag(text, cls){ return '<span class="tag '+(cls||'t-n')+'"><i class="dot"></i>'+esc(text||'—')+'</span>'; }
  function statusTag(s){
    var m={'Draft':'t-n','Pending Approval':'t-y','Approved':'t-g','Rejected':'t-r','Sent Back':'t-p','Posted':'t-b','Withdrawn':'t-n'};
    return tag(s||'—',m[s]||'t-n');
  }
  function decisionTag(s){
    var m={'Pending':'t-y','Approved':'t-g','Rejected':'t-r','Sent Back':'t-p','Skipped':'t-n'};
    return tag(s||'Pending',m[s]||'t-n');
  }
  function ph(kicker,title,desc,actions){
    var hp=helpForRoute();
    return '<div class="ph"><div style="min-width:240px;flex:1"><div class="kicker">'+esc(kicker)+'</div><h2>'+esc(title)+'</h2><p>'+esc(desc||'')+'</p></div><div class="btnrow">'+(actions||'')+helpButton()+'</div></div>'+
      (hp?'<div class="clue"><span class="qm">i</span><span class="tx"><b>Quick guide · </b>'+hp.c+'</span><span class="go" onclick="lifeDCR.helpModal()">Show me how</span></div>':'');
  }
  function tile(k,v,d,cls,click){
    return '<div class="tile '+(cls||'')+'"'+(click?' onclick="'+click+'"':'')+'><div class="v tnum">'+esc(v)+'</div><div class="k">'+esc(k)+'</div><div class="d">'+esc(d||'')+'</div></div>';
  }
  function card(title,sub,body,opt){
    opt=opt||{};
    return '<div class="card '+(opt.cls||'')+'"><header>'+(opt.ic?'<i class="ic sm '+(opt.icCls||'')+'">'+opt.ic+'</i>':'')+'<h3>'+esc(title)+'</h3>'+(sub?'<span class="sub">'+esc(sub)+'</span>':'')+'<div class="sp"></div>'+(opt.act||'')+'</header><div class="body'+(opt.flush?' flush':'')+'">'+body+'</div></div>';
  }
  function sectionHead(title,sub){
    return '<div class="shead"><span class="ltr">•</span><b>'+esc(title)+'</b><span class="sub">'+esc(sub||'')+'</span><div class="sp"></div><span class="cv">▼</span></div>';
  }
  function emptyBlock(title,sub){ return '<div class="empty"><b>'+esc(title)+'</b>'+esc(sub||'')+'</div>'; }
  function requestScopeText(){
    var c=S.context||{};
    if(c.view_all)return S.branch?S.branch:'All permitted branches';
    if((c.branches||[]).length>1)return 'My branches';
    return c.branch||((c.branches||[])[0])||'My branch';
  }
  function role(){ return (S.context||{}).access_role||''; }
function canRaise(){
  return [
    'Branch User',
    'Branch Manager',
    'Operations',
    'HR',
    'Accounts',
    'Audit',
    'DCEO',
    'COO',
    'IT'
  ].indexOf(role())>=0;
} 
function canApprove(){ return !!((S.context||{}).is_dcr_admin) || ['Branch Manager','Operations','HR','Accounts','Audit','DCEO','COO'].indexOf(role())>=0; }
  function canApply(){
      var c = S.context || {};
      if (c.is_dcr_admin) return true;
      if (c.is_system_manager) return true;
      return ['Accounts','COO'].indexOf(role()) >= 0;
    }
  function canControl(){ return ['Audit','DCEO','COO','IT'].indexOf(role())>=0; }

  /* ============================================================
     ORIGINAL PM DESIGN HELP + GUIDE CONFIG
     Static business guidance only. No sample transactional data.
     ============================================================ */
  var PAGE_HELP={
    dash:{c:'This is the control screen. The seven counters read left to right, worst news last.',s:['Read the counters first — open requests, records frozen, what is waiting on you, and anything that needs attention.','Anything sitting in <b>What needs you</b> has a correction request behind it. Clear it and the request can move to the next stage.','Use the branch filter at the top to narrow the whole module to one permitted branch.'],n:['A branch that keeps raising corrections has a data-capture problem, not a paperwork problem.','All numbers on this live page come from ERPNext Data Correction records — no sample transactions are displayed.']},
    guide:{c:'The full rulebook — the five stages, the process age, the evidence, and what each correction category is for.',s:['Read the five-stage flow once before raising your first request.','Check the process-age table so you know what to expect.','Scroll to your category and read what it is <b>not</b> for — that is where most rejections come from.'],n:['Each configured live rule appears under the matching category on this screen.']},
    new:{c:'Four steps. Choose the data → find the record → correct it → submit. Nothing changes until it is approved.',s:['<b>Step 1</b> — pick the configured correction rule for the exact field that is wrong.','<b>Step 2</b> — search the live ERPNext record and select the exact document.','<b>Step 3</b> — compare the present value with the requested value and attach the required evidence.','<b>Step 4</b> — review the approval chain and submit.'],n:['A rule marked evidence required will not submit until the minimum number of files is attached.','The approved value, not necessarily the originally requested value, is what is posted.']},
    requests:{c:'Every live correction request in your permitted scope, with the step it has reached and who is holding it.',s:['Use search and status filters to narrow the register.','Open any row to see the change, approval trail and evidence.','A frozen badge means the source record is still under correction control.'],n:['No seeded or sample request rows are used in this register.']},
    approvals:{c:'Requests sitting on your desk right now. Each one is waiting for your resolved approval role.',s:['Read the reason and before/after values first.','Check the evidence before approving.','Approve, reject or send back with remarks.'],n:['The backend verifies the current approval stage again before accepting your decision.']},
    post:{c:'Approved corrections that have not yet been written to the source record.',s:['Check the final approved value before posting.','Posting writes the correction to the live source document.','After posting the request is marked Posted and the hold is released.'],n:['Posting is a live ERP data change and is restricted to the configured posting roles.']},
    holds:{c:'Entries frozen because a correction is pending against them.',s:['Open the request to see why the record is frozen.','Resolve the approval chain to release the hold.','The hold indicator comes from the live LIFE Data Correction Request record.'],n:['This screen contains no mock hold rows.']},
    reports:{c:'Correction volume is a control signal. Use live requests to see where corrections are accumulating.',s:['Start with category to see which kind of data is being corrected most often.','Then use branch and status to narrow the pattern.','Open the register for request-level detail.'],n:['This live report uses LIFE Data Correction Request records only.']},
    rules:{c:'The correction master defines the source DocType, field, evidence and approval chain.',s:['Each enabled rule controls one live source field.','Evidence requirements and approval stages are read from LIFE Data Correction Rule.','Only configured rules can be raised from the live wizard.'],n:['Add or change rules in the master rather than hard-coding fields in the Web Page.']},
    access:{c:'This screen explains the access resolved for the currently logged-in ERPNext user.',s:['The backend reads the current session user.','It resolves Employee, designation, branch and additional branches.','The returned access role controls which Web Page actions are visible.'],n:['Access is checked again by the API for every live action.']}
  };
  var GUIDE_CATEGORIES=[
    {key:'Billing',name:'Billing Corrections',icon:'₹',cls:'gold',cap:'Anything printed on a raised bill',what:'Corrects a bill that is already in the system. The bill number remains the reference while the approved field value is corrected.',when:'The bill exists and a value on the existing record is wrong.',notfor:'Giving a fresh concession after the sale. That is a new commercial decision, not a data correction.',effect:'Billing, collections, tax or incentive reporting may move depending on the configured field.'},
    {key:'Therapy Session',name:'Session Entries',icon:'⧉',cls:'teal',cap:'Execution register — what was actually done',what:'Corrects an existing therapy-session entry such as date, quantity, therapist, therapy or status.',when:'The session physically happened differently from what the ERP record says.',notfor:'Adding a session that was never performed.',effect:'Plan balance, therapist productivity and execution reporting may change.'},
    {key:'Voucher',name:'Voucher Entry',icon:'▧',cls:'plum',cap:'Posted branch expenditure',what:'Corrects an already-posted expenditure or voucher record against its supporting document.',when:'The supporting bill or payment proof differs from the value that was keyed.',notfor:'Adding an expense that was never posted. Raise the proper expense transaction instead.',effect:'Expense reporting, branch profitability and cash/bank reporting may change.'},
    {key:'Cancellation',name:'Invoice Cancellation',icon:'✕',cls:'rose',cap:'Voiding a bill in full',what:'Handles a configured full-cancellation correction where the original invoice should not remain active.',when:'The configured cancellation rule and evidence conditions are satisfied.',notfor:'Reducing a bill value. Use the appropriate billing field correction instead.',effect:'Revenue, outstanding and related accounting treatment may be affected.'},
    {key:'Client',name:'Client Data Correction',icon:'☺',cls:'slate',cap:'The client master file',what:'Corrects configured fields on the live Patient/Client master.',when:'The client or supporting identity/clinical document confirms the correct detail.',notfor:'Changing one transaction when the client master itself is already correct.',effect:'Communication, follow-up and future transactions read from the corrected master value.'},
    {key:'Employee',name:'Employee Details Corrections',icon:'☰',cls:'amber',cap:'The employee master file',what:'Corrects configured Employee master fields such as identity, posting or payroll-related data.',when:'HR has the supporting document or approved transfer/master-data evidence.',notfor:'Salary revision, promotion or another HR transaction that has its own process.',effect:'Attendance, payroll, statutory or organizational reporting may change depending on the field.'},
    {key:'Other',name:'Other Data Correction',icon:'⊕',cls:'slate',cap:'Anything not covered by the standard categories',what:'A controlled correction for a case that does not fit the standard configured categories.',when:'A specific enabled LIFE Data Correction Rule exists for that case.',notfor:'Bypassing a standard category because its evidence or approval chain is stricter.',effect:'Depends on the configured source DocType and field.'}
  ];
  var SEC_STATE={},SEC_INDEX=0,ZOOM=2;
  function helpForRoute(){return PAGE_HELP[S.route]||null;}
  function helpButton(){return helpForRoute()?'<span class="hbtn" onclick="lifeDCR.helpModal()"><i>?</i> How to use this screen</span>':'';}

  function call(action,args){
    args=args||{}; args.action=action;
    return new Promise(function(resolve,reject){
      if(!window.frappe||!frappe.call){ reject(new Error('Frappe client is not available on this page.')); return; }
      frappe.call({
        method:API, args:args, freeze:false,
        callback:function(r){ if(r&&r.message){resolve(r.message);return;} reject(new Error('No response from Data Correction API.')); },
                error:function(err){
          var msg = 'Data Correction API request failed.';

          try{
            if (err && err.responseJSON) {
              var smRaw = err.responseJSON._server_messages;

              if (smRaw) {
                var sm = smRaw;
                if (typeof sm === "string") {
                  try { sm = JSON.parse(sm); } catch(e){}
                }

                if (Array.isArray(sm) && sm.length) {
                  var first = sm[0];
                  if (typeof first === "string") {
                    try { first = JSON.parse(first); } catch(e){}
                  }
                  if (first && first.message) {
                    msg = String(first.message);
                  }
                }
              } else if (err.responseJSON.exception) {
                msg = String(err.responseJSON.exception);
              } else if (err.responseJSON._error_message) {
                msg = String(err.responseJSON._error_message);
              }
            } else if (err && err.message) {
              msg = String(err.message);
            }
          }catch(e){}

          // Strip HTML
          msg = String(msg)
            .replace(/<br\s*\/?>/gi, '\n')
            .replace(/<\/(div|p|li|h[1-6])>/gi, '\n')
            .replace(/<[^>]+>/g, '')
            .replace(/&nbsp;/g, ' ')
            .replace(/&amp;/g, '&')
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#039;/g, "'")
            .replace(/[ \t]+\n/g, '\n')
            .replace(/\n{3,}/g, '\n\n')
            .trim();

          // Tag the message so the UI can decide how to show it.
          if (/do not exist as records in the linked DocType/i.test(msg)
              || /Could not find .*: /i.test(msg)
              || /is not a valid .* record/i.test(msg)) {
            msg = '[LINK] ' + msg;
          } else if (/source document has changed since this request/i.test(msg)) {
            msg = '[STALE] ' + msg;
          } else if (/not in 'Approved' state/i.test(msg)) {
            msg = '[STATE] ' + msg;
          } else if (/already posted on/i.test(msg)) {
            msg = '[DUP] ' + msg;
          } else if (/Failed to write to /i.test(msg)) {
            msg = '[WRITE] ' + msg;
          } else if (/Only Accounts, COO or a System Manager can post/i.test(msg)) {
            msg = '[PERM] ' + msg;
          }

          reject(new Error(msg));
        }
      });
    });
  }

  function setBusy(text){
    var w=byId('wrap'); if(w)w.innerHTML='<div class="card"><div class="body"><div class="life-loading"><span class="life-spinner"></span>'+esc(text||'Loading…')+'</div></div></div>';
  }
  function accessError(err){
    var w=byId('wrap');
    if(w)w.innerHTML='<div class="life-access-denied"><div class="card acc-r"><header><h3>Data Correction access unavailable</h3></header><div class="body"><div class="note n-c"><b>Unable to open this module</b>'+esc(err&&err.message?err.message:String(err||'Access denied'))+'</div></div></div></div>';
    var side=byId('life-dcr-side'); if(side)side.style.display='none';
  }

  async function bootstrap(){
    try{
      setBusy('Reading logged-in user and live correction settings…');
      var boot=await call('bootstrap');
      S.context=boot.context||{};

      // bootstrap intentionally returns a compact rule list. Fetch the full
      // Rule records so evidence, routing and child-field settings are available.
      var ruleRes=await call('list_rules');
      S.rules=ruleRes.rows||boot.rules||[];
      S.ready=true;

      applyContext();
      await loadRequests({silent:true});
      if(canApprove())await loadApprovals();else S.approvals=[];
      calculateDashboard();
      renderNav();
      bindStaticEvents();
      await go('dash');
    }catch(e){
      console.error('[LIFE DCR bootstrap]',e);
      accessError(e);
    }
  }

  function applyContext(){
    var c=S.context||{};
    if(byId('u-name'))byId('u-name').textContent=c.name||c.user||'User';
    if(byId('u-role'))byId('u-role').textContent=(c.is_dcr_admin?'DCR Admin':(c.access_role||'No access'))+(c.branch?' · '+c.branch:'');
    if(byId('u-ini'))byId('u-ini').textContent=ini(c.name||c.user);
    if(byId('fc-rr'))byId('fc-rr').textContent=c.is_dcr_admin?'DCR Admin':(c.access_role||'—');
    if(byId('fc-scope'))byId('fc-scope').textContent=requestScopeText();
    if(byId('fc-d'))byId('fc-d').textContent=todayText();
    buildBranchFilter();
