  function buildBranchFilter(){
    var sel=byId('brsel'); if(!sel)return;
    var c=S.context||{}, options=[];
    if(c.view_all){
      var found={};
      (S.allRequests||S.requests||[]).forEach(function(x){if(x.branch)found[x.branch]=1;});
      options=Object.keys(found).sort();
    }else options=(c.branches||[]).slice();
    var h='<option value="">'+(c.view_all?'All branches':'All my branches')+'</option>';
    options.forEach(function(b){h+='<option value="'+attr(b)+'">'+esc(b)+'</option>';});
    sel.innerHTML=h;
    if(options.indexOf(S.branch)<0)S.branch='';
    sel.value=S.branch;
  }

