  function updateNavBadges(){
    var vals={
      approvals:(S.approvals||[]).length,
      holds:(S.requests||[]).filter(function(r){return Number(r.is_on_hold)===1;}).length
    };
    Object.keys(vals).forEach(function(k){
      var el=byId('pl-'+k); if(!el)return;
      el.textContent=vals[k]||'';
      el.style.display=vals[k]?'':'none';
