  function markRoute(){
    document.querySelectorAll('#nav a[data-route]').forEach(function(a){a.classList.toggle('on',a.getAttribute('data-route')===S.route);});
  }
  function bindStaticEvents(){
    var q=byId('gq');
    if(q){
      var t=null;
      q.addEventListener('input',function(){clearTimeout(t);t=setTimeout(function(){S.search=q.value||'';S.page=1;go('requests');},350);});
    }
    var b=byId('brsel');
    if(b)b.addEventListener('change',function(){S.branch=b.value||'';S.page=1;if(byId('fc-scope'))byId('fc-scope').textContent=requestScopeText();go(S.route);});
    var ov=byId('ov');
    if(ov&&!ov.getAttribute('data-life-bound')){
      ov.setAttribute('data-life-bound','1');
      ov.addEventListener('click',function(e){
        if(e.target===ov)closeModal();
      });
    }

    if(!document.documentElement.getAttribute('data-life-dcr-esc-bound')){
      document.documentElement.setAttribute('data-life-dcr-esc-bound','1');
      document.addEventListener('keydown',function(e){
        if(e.key==='Escape'){
          var current=byId('ov');
          if(current&&current.classList.contains('on')){
            e.preventDefault();
            closeModal();
          }
        }
      });
    }
