  async function go(routeName){
    if(!S.ready)return;
    S.route=routeName||'dash';
    var routeGroup={dash:'COMMAND',guide:'COMMAND',new:'CORRECTION DESK',requests:'CORRECTION DESK',approvals:'CORRECTION DESK',detail:'CORRECTION DESK',post:'CORRECTION DESK',holds:'RECORDS',reports:'ANALYSIS',rules:'SETTINGS',access:'SETTINGS'};
    if(routeGroup[S.route])S.openGroup=routeGroup[S.route];
    renderNav();
    var side=byId('life-dcr-side'); if(side)side.classList.remove('show');
    try{
      if(S.route==='dash'){await loadDashboard();await loadRequests({silent:true});if(canApprove())await loadApprovals();else S.approvals=[];renderDashboard();}
      else if(S.route==='requests'){await loadRequests();renderRequests();}
      else if(S.route==='approvals'){await loadApprovals();renderApprovals();}
      else if(S.route==='detail'){renderRequestPage();}
      else if(S.route==='new'){renderNew();}
      else if(S.route==='holds'){await loadRequests({silent:true});renderHolds();}
      else if(S.route==='reports'){await loadRequests({silent:true});renderReports();}
      else if(S.route==='rules'){renderRules();}
      else if(S.route==='guide'){renderGuide();}
      else if(S.route==='post'){await loadRequests({silent:true});renderApprovedForPost();}
      else if(S.route==='access'){renderAccessInfo();}
      else {S.route='dash';renderDashboard();}
      decoratePage();
    }catch(e){
      console.error('[LIFE DCR route '+S.route+']',e); toast(e.message||'Unable to load','err');
      if(byId('wrap'))byId('wrap').innerHTML=card('Unable to load','', '<div class="note n-c"><b>Request failed</b>'+esc(e.message||e)+'</div>',{cls:'acc-r'});
    }
  }

 function renderApprovedForPost(){
  if(!canApply()){
    byId('wrap').innerHTML = ph(
      'CORRECTION DESK · APPLY & POST',
      'No posting rights',
      'Only Accounts, COO or a System Manager may apply an approved correction to the source record.',
      ''
    );
    return;
  }

  var rows=(S.requests||[]).filter(function(r){return r.status==='Approved';});

  var h=ph(
    'CORRECTION DESK · APPLY & POST',
    'Approved corrections ready to post',
    'Approval alone changes nothing. Posting writes the final approved values into the source document, releases the hold, and files the correction. This cannot be undone.',
    ''
  );

  h+='<div class="note n-a" style="margin-bottom:12px">'
    +'<b>Live write-back to the source document</b>'
    +'Posting will modify the actual ERPNext record. The source-modified guard, the branch scope check and the approval trail are all re-verified server-side before anything is written.</div>';

  h+=card(
    'Approved — waiting to post',
    rows.length+' request(s)',
    postTable(rows),
    {cls:'acc-g', flush:true}
  );

  byId('wrap').innerHTML=h;
}

function postTable(rows){
  rows=rows||[];
  if(!rows.length) return emptyBlock('Nothing waiting to be posted',
    'Approved requests appear here the moment the last approver clears them.');

  var h='<div class="tw"><table class="tb"><thead><tr>'
    +'<th>Request</th><th>Branch</th><th>Category</th><th>Source</th>'
    +'<th>Approved value(s)</th><th>Final approved</th><th></th></tr></thead><tbody>';

  rows.forEach(function(r){
    var changes = r.changes || [];
    var approvedList = changes.map(function(c){
      var finalVal = (c.approved_value != null && String(c.approved_value) !== '')
        ? c.approved_value : c.requested_value;
      return '<div><b>'+esc(c.field_label||c.field_name)+'</b>'
        +' <span class="sm2">'+esc(c.old_value||'')+' → </span>'
        +'<b class="pos">'+esc(finalVal==null?'':finalVal)+'</b></div>';
    }).join('');

    h+='<tr class="click" onclick="lifeDCR.openRequest(\''+attr(r.name)+'\')">'
      +'<td><div class="mono nm">'+esc(r.name)+'</div>'
      +'<div class="sm2">'+esc(r.requested_by_name||r.requested_by||'')+'</div></td>'
      +'<td>'+esc(r.branch||'—')+'</td>'
      +'<td>'+esc(r.category||'—')+'</td>'
      +'<td><div class="nm">'+esc(r.source_document||'—')+'</div>'
      +'<div class="sm2">'+esc(r.source_doctype||'')+'</div></td>'
      +'<td class="sm2">'+(approvedList||'<span class="sm2">no change rows</span>')+'</td>'
      +'<td class="sm2">'+esc(r.final_approved_on? fmtDT(r.final_approved_on): '—')+'</td>'
      +'<td class="r">'
        +'<button class="btn sm g" onclick="event.stopPropagation();lifeDCR.openRequest(\''+attr(r.name)+'\')">Review</button> '
        +'<button class="btn sm p" onclick="event.stopPropagation();lifeDCR.applyModal(\''+attr(r.name)+'\')">Post</button>'
      +'</td></tr>';
  });
  h+='</tbody></table></div>';
  return h;
}

