  function calculateDashboard(){
    var rows=S.requests||[];
    S.dashboard={
      pending:rows.filter(function(r){return r.status==='Pending Approval';}).length,
      sent_back:rows.filter(function(r){return r.status==='Sent Back';}).length,
      approved:rows.filter(function(r){return r.status==='Approved';}).length,
      posted:rows.filter(function(r){return r.status==='Posted';}).length,
      rejected:rows.filter(function(r){return r.status==='Rejected';}).length,
      on_hold:rows.filter(function(r){return Number(r.is_on_hold)===1;}).length
    };
  }

  async function loadDashboard(){
    // No separate dashboard API is required. Counters are derived from the
    // already-authorized request list returned by list_requests.
    calculateDashboard();
    return S.dashboard;
  }

  async function loadRequests(opt){
    opt=opt||{};
    if(!opt.silent)setBusy('Loading live correction requests…');

    // The current API enforces user/branch access itself. Search and branch
    // filtering are intentionally handled here so the frontend matches the
    // exact current API contract.
    var res=await call('list_requests',{});
    S.allRequests=(res.rows||[]).slice();

    var rows=S.allRequests.slice();
    if(S.branch)rows=rows.filter(function(r){return clean(r.branch)===clean(S.branch);});
    if(S.status)rows=rows.filter(function(r){return clean(r.status)===clean(S.status);});
    if(S.search){
      var q=clean(S.search).toLowerCase();
      rows=rows.filter(function(r){
        return [r.name,r.source_document,r.source_display_name,r.requested_by_name,r.requested_by,r.category,r.branch]
          .join(' ').toLowerCase().indexOf(q)>=0;
      });
    }
    S.requests=rows;
    buildBranchFilter();
    calculateDashboard();
  }

