  function filterStatus(st){ S.status=st||''; S.page=1; go('requests'); }

  function requestTable(rows,compact){
    rows=rows||[];
    if(!rows.length)return emptyBlock('No correction requests','No live records match this view.');
    var h='<div class="tw"><table class="tb'+(compact?' life-compact':'')+'"><thead><tr><th>Request</th><th>Branch</th><th>Category</th><th>Source</th><th>Stage</th><th>Status</th><th>Hold</th><th></th></tr></thead><tbody>';
    rows.forEach(function(r){
      h+='<tr class="click" onclick="lifeDCR.openRequest(\''+attr(r.name)+'\')">'+
        '<td><div class="nm mono">'+esc(r.name)+'</div><div class="sm2">'+esc(r.requested_by_name||r.requested_by||'')+' · '+fmtDT(r.requested_on)+'</div></td>'+
        '<td>'+esc(r.branch||'—')+'</td>'+
        '<td>'+esc(r.category||'—')+'</td>'+
        '<td><div class="nm">'+esc(r.source_document||'—')+'</div><div class="sm2">'+esc(r.source_doctype||'')+'</div></td>'+
        '<td>'+esc(r.workflow_stage||'—')+'</td>'+
        '<td>'+statusTag(r.status)+'</td>'+
        '<td>'+(Number(r.is_on_hold)?'<span class="hold">🔒 Frozen</span>':'—')+'</td>'+
