  function renderRequests(){
    var statusOpts=['','Draft','Pending Approval','Approved','Sent Back','Posted','Rejected','Withdrawn'];
    var toolbar='<div class="filters"><div class="fl grow"><label>Search</label><input id="rq-search" value="'+attr(S.search)+'" placeholder="DCR no, source record, requester"></div>'+
      '<div class="fl"><label>Status</label><select id="rq-status">'+statusOpts.map(function(x){return '<option value="'+attr(x)+'"'+(S.status===x?' selected':'')+'>'+(x||'All statuses')+'</option>';}).join('')+'</select></div>'+
      '<button class="btn p" onclick="lifeDCR.applyRequestFilters()">Apply</button><button class="btn" onclick="lifeDCR.clearRequestFilters()">Clear</button>'+
      (canRaise()?'<button class="btn g" onclick="lifeDCR.go(\'new\')">＋ New</button>':'')+'</div>';
    var rows=S.requests||[], total=rows.length, pages=Math.max(1,Math.ceil(total/S.pageSize));
    if(S.page>pages)S.page=pages;
    var start=(S.page-1)*S.pageSize, pageRows=rows.slice(start,start+S.pageSize);
    var h=ph('CORRECTION DESK · LIVE REGISTER','Data Correction Requests',total+' live request(s) in the current scope. No sample records are used.','');
    h+=toolbar;
    h+=card('Request register',total+' result(s)',requestTable(pageRows,false)+pagination(total,pages),{cls:'acc',flush:true});
    byId('wrap').innerHTML=h;
  }

  function pagination(total,pages){
    if(total<=S.pageSize)return '';
    var h='<div class="life-pagination"><span class="sm2">'+total+' records</span><button class="pg" '+(S.page<=1?'disabled':'')+' onclick="lifeDCR.setPage('+(S.page-1)+')">‹</button>';
    var from=Math.max(1,S.page-2),to=Math.min(pages,from+4); from=Math.max(1,to-4);
    for(var i=from;i<=to;i++)h+='<button class="pg '+(i===S.page?'on':'')+'" onclick="lifeDCR.setPage('+i+')">'+i+'</button>';
    h+='<button class="pg" '+(S.page>=pages?'disabled':'')+' onclick="lifeDCR.setPage('+(S.page+1)+')">›</button></div>';
    return h;
  }
  function setPage(p){ S.page=Math.max(1,p||1); renderRequests(); }
