  function chainForRule(r){
    var out=[];
    if(r.branch_manager_approval)out.push('Branch Manager');
    if(r.operations_approval)out.push('Operations');
    if(r.hr_approval)out.push('HR');
    if(r.accounts_approval)out.push('Accounts');
    if(r.audit_approval)out.push('Audit');
    if(r.dceo_approval)out.push('DCEO');
    if(r.coo_approval)out.push('COO');
    return out;
