  function renderReports(){
    var rows=S.requests||[],byCat={},byStatus={},byBranch={};
    rows.forEach(function(r){var c=clean(r.category)||'Uncategorised',st=clean(r.status)||'Unknown',br=clean(r.branch)||'No branch';byCat[c]=(byCat[c]||0)+1;byStatus[st]=(byStatus[st]||0)+1;byBranch[br]=(byBranch[br]||0)+1;});
    function tableFrom(map,label){var keys=Object.keys(map).sort(function(a,b){return map[b]-map[a]||a.localeCompare(b);});if(!keys.length)return emptyBlock('No live data','No requests match the current scope.');return '<div class="tw"><table class="tb"><thead><tr><th>'+esc(label)+'</th><th class="r">Requests</th></tr></thead><tbody>'+keys.map(function(k){return '<tr><td>'+esc(k)+'</td><td class="r tnum"><b>'+map[k]+'</b></td></tr>';}).join('')+'</tbody></table></div>';}
    var h=ph('ANALYSIS · LIVE REQUESTS','Correction Reports','A live control view built only from LIFE Data Correction Request records in your current scope.','');
    h+=sectionHead('Category view','where corrections are being raised');
    h+='<div class="grid g3">'+card('By category','live request volume',tableFrom(byCat,'Category'),{cls:'acc-g',flush:true})+card('By status','where requests are sitting',tableFrom(byStatus,'Status'),{cls:'acc-t',flush:true})+card('By branch','branch-level volume',tableFrom(byBranch,'Branch'),{cls:'acc',flush:true})+'</div>';
