  function typeForField(fieldtype){
    var ft=clean(fieldtype);
    if(ft==='Int')return 'Int';
    if(ft==='Float'||ft==='Percent')return 'Float';
    if(ft==='Currency')return 'Currency';
    if(ft==='Date')return 'Date';
    if(ft==='Datetime')return 'Datetime';
    if(ft==='Check')return 'Check';
    if(ft==='Link')return 'Link';
    if(ft==='Text'||ft==='Small Text'||ft==='Long Text'||ft==='Text Editor')return 'Text';
    return 'Data';
  }

  function inputForValue(id,value,fieldtype){
    var ft=clean(fieldtype),v=value==null?'':String(value);
    if(ft==='Date')return '<input type="date" id="'+attr(id)+'" value="'+attr(v.slice(0,10))+'" data-old="'+attr(v)+'">';
    if(ft==='Check')return '<select id="'+attr(id)+'" data-old="'+attr(v)+'"><option value="0"'+(String(v)==='0'||v===''?' selected':'')+'>No</option><option value="1"'+(String(v)==='1'?' selected':'')+'>Yes</option></select>';
    if(ft==='Small Text'||ft==='Long Text'||ft==='Text'||ft==='Text Editor')return '<textarea id="'+attr(id)+'" rows="2" data-old="'+attr(v)+'">'+esc(v)+'</textarea>';
    var type=(ft==='Int'||ft==='Float'||ft==='Currency'||ft==='Percent')?'number':'text';
    var step=(ft==='Int')?'1':((ft==='Float'||ft==='Currency'||ft==='Percent')?'0.01':'');
    return '<input type="'+type+'" '+(step?'step="'+step+'" ':'')+'id="'+attr(id)+'" value="'+attr(v)+'" data-old="'+attr(v)+'">';
  }

