        ft !== 'Table MultiSelect'
      );
    });

    if (simpleValues.length) {
      h += '<div class="life-change-editor">';

      simpleValues.forEach(function(v, i) {
        h +=
          '<div class="fg">' +
            '<label>' +
              esc(v.field_label || v.field_name) +
              ' <span class="sm2 mono">' +
                esc(v.field_name || '') +
              '</span>' +
            '</label>' +

            inputForValue(
              'change-simple-' + i,
              v.value,
              v.fieldtype
            ) +
          '</div>';
      });

      h +=
        '</div>' +
        '<div class="sm2" style="margin-top:6px">' +
          'Only values that you actually change will be submitted.' +
        '</div>';
    }

    if(childRows.length){
      var fields=[];
      [r.child_value_field,r.secondary_field,r.third_field].forEach(function(f){f=clean(f);if(f&&fields.indexOf(f)<0)fields.push(f);});
      fields=fields.filter(function(f){return childRows.some(function(row){return Object.prototype.hasOwnProperty.call(row,f);});});
      if(!fields.length && r.child_value_field)fields=[r.child_value_field];

      h+='<div class="sec" style="margin-top:12px"><b>Child rows</b><span>Edit only the row values that are wrong</span><i></i></div>';
      h+='<div class="tw"><table class="tb"><thead><tr><th>Row</th>'+fields.map(function(f){return '<th>'+esc(f)+'</th>';}).join('')+'</tr></thead><tbody>';
      childRows.forEach(function(row,ri){
        var label=row.item_name||row.item_code||row.account||row.account_head||row.description||('Row '+(row.idx||ri+1));
        h+='<tr><td><b>'+esc(label)+'</b><div class="sm2 mono">'+esc(row.name||'')+'</div></td>';
        fields.forEach(function(f,fi){var v=row[f];h+='<td>'+inputForValue('change-child-'+ri+'-'+fi,v,'Data')+'</td>';});
        h+='</tr>';
      });
      h+='</tbody></table></div><div id="life-child-meta" data-fields="'+attr(JSON.stringify(fields))+'"></div>';
    }

    if(!values.length&&!childRows.length){
      if(clean(r.execution_type)==='ACTION'){
        h+='<div class="note n-w"><b>Action request</b>This correction requests the configured action <strong>'+esc(r.action_name||r.field_label||'Action')+'</strong>. No source field is edited directly from the Web Page.</div>';
      }else if(clean(r.execution_type)==='MANUAL'){
        h+='<div class="fg"><label>Requested correction <span class="rq">*</span></label><textarea id="manual-requested-value" rows="4" data-old="" placeholder="Describe the exact approved correction to be carried out"></textarea></div>';
      }else{
        h+='<div class="note n-w"><b>No editable value returned</b>The selected rule does not currently expose a source field through get_source.</div>';
      }
    }
    host.className='';
    host.innerHTML=h;
  }

  function buildChangesFromEditor() {
  var res = S.selectedSourceData || {};
  var r = selectedRule();
  var out = [];

  var simpleValues =
    (res.values || []).filter(function(v) {
      var ft = clean(v.fieldtype);

      return (
        ft !== 'Table' &&
        ft !== 'Table MultiSelect'
      );
    });

  simpleValues.forEach(function(v, i) {
      var el=byId('change-simple-'+i);if(!el)return;
      var old=String(el.getAttribute('data-old')||''), now=String(el.value==null?'':el.value);
      if(now!==old){
        out.push({field_name:v.field_name||'',field_label:v.field_label||v.field_name||'',old_value:old,requested_value:now,value_type:typeForField(v.fieldtype),fieldtype:v.fieldtype||'',link_doctype:v.options||''});
      }
    });

    var childRows=res.child_rows||[],meta=byId('life-child-meta'),fields=[];
    if(meta){try{fields=JSON.parse(meta.getAttribute('data-fields')||'[]')||[];}catch(e){fields=[];}}
    childRows.forEach(function(row,ri){
      fields.forEach(function(f,fi){
        var el=byId('change-child-'+ri+'-'+fi);if(!el)return;
        var old=String(el.getAttribute('data-old')||''),now=String(el.value==null?'':el.value);
        if(now!==old){
          var table=clean(r.child_table_field)||'child';
          var path=table+'.'+(row.name||('row'+(row.idx||ri+1)))+'.'+f;
          var label=(row.item_name||row.item_code||row.account||row.account_head||('Row '+(row.idx||ri+1)))+' · '+f;
          out.push({field_name:path,field_label:label,old_value:old,requested_value:now,value_type:'Data',fieldtype:'Data',change_remarks:'Child row: '+(row.name||row.idx||'')});
        }
      });
    });

    if(!out.length && clean(r.execution_type)==='ACTION'){
      out.push({field_name:'#action',field_label:r.field_label||r.action_name||'Action',old_value:'Active',requested_value:r.action_name||'cancel',value_type:'Data',fieldtype:'Data'});
    }
    if(!out.length && clean(r.execution_type)==='MANUAL'){
      var el=byId('manual-requested-value'),v=clean(el?el.value:'');
      if(v)out.push({field_name:'#manual',field_label:r.field_label||'Requested correction',old_value:'',requested_value:v,value_type:'Text',fieldtype:'Long Text'});
    }
    return out;
  }

  async function uploadSelected(n){
    var input=byId('file-'+n), status=byId('file-status-'+n); if(!input||!input.files||!input.files[0])return;
    var file=input.files[0]; if(status)status.innerHTML='<span class="life-spinner"></span> Uploading '+esc(file.name)+'…';
    try{
      var fd=new FormData(); fd.append('file',file);fd.append('is_private','1');fd.append('folder','Home/Attachments');
      var headers={}; if(window.frappe&&frappe.csrf_token)headers['X-Frappe-CSRF-Token']=frappe.csrf_token;
      var response=await fetch('/api/method/upload_file',{method:'POST',headers:headers,body:fd,credentials:'same-origin'});
      var data=await response.json();
      if(!response.ok||!data.message||!data.message.file_url)throw new Error((data&&data.exception)||'Upload failed');
      S.uploaded[n-1]=data.message.file_url;
      if(status)status.innerHTML='<b>Uploaded</b> '+esc(file.name);
    }catch(e){S.uploaded[n-1]='';if(status)status.innerHTML='<span class="neg">Upload failed</span>';toast('Attachment upload failed: '+e.message,'err');}
  }

  async function submitRequest(){
    var r=selectedRule();
    if(!r){toast('Select a correction rule.','wn');return;}
    if(!S.selectedSource){toast('Select the live source record.','wn');return;}
    var reason=clean(byId('reason')?byId('reason').value:'');
    if(!reason){toast('Reason is required.','wn');return;}

    var changes=buildChangesFromEditor();
    if(!changes.length){toast('Change at least one value before submitting.','wn');return;}

    if(Number(r.evidence_required)){
      var count=S.uploaded.filter(Boolean).length, min=Math.max(1,Number(r.minimum_attachments||1));
      if(count<min){toast('Upload at least '+min+' attachment(s).','wn');return;}
    }

    if(!window.confirm('Submit this Data Correction request for approval?\n\nSource: '+S.selectedSource+'\nRule: '+(r.rule_name||r.name)+'\nChanges: '+changes.length))return;

    var btn=byId('submit-request');
    if(btn){btn.disabled=true;btn.textContent='Submitting…';}
    try{
      var requestPayload = {
        rule: r.name,
        source_document: S.selectedSource,
        source_display_name: sourceDisplayName(),
        reason: reason,
        changes: changes,
        attachments: S.uploaded.filter(Boolean)
      };

      console.log('[LIFE DCR create_request payload]', requestPayload);

      // Send ONLY scalar arguments to Frappe Server Script.
      // Nested arrays are flattened because this site's Web Page call path
      // is not reliably preserving JSON/list arguments.
      var createArgs = {
        rule: requestPayload.rule,
        source_document: requestPayload.source_document,
        source_display_name: requestPayload.source_display_name,
        reason: requestPayload.reason,
        change_count: String(requestPayload.changes.length),
        attachment_count: String(requestPayload.attachments.length)
      };

      requestPayload.changes.forEach(function(ch, i){
        var p = 'change_' + i + '_';
        createArgs[p + 'field_name'] = ch.field_name == null ? '' : String(ch.field_name);
        createArgs[p + 'field_label'] = ch.field_label == null ? '' : String(ch.field_label);
        createArgs[p + 'old_value'] = ch.old_value == null ? '' : String(ch.old_value);
        createArgs[p + 'requested_value'] = ch.requested_value == null ? '' : String(ch.requested_value);
        createArgs[p + 'value_type'] = ch.value_type == null ? '' : String(ch.value_type);
        createArgs[p + 'fieldtype'] = ch.fieldtype == null ? '' : String(ch.fieldtype);
        createArgs[p + 'link_doctype'] = ch.link_doctype == null ? '' : String(ch.link_doctype);
        createArgs[p + 'change_remarks'] = ch.change_remarks == null ? '' : String(ch.change_remarks);
      });

      requestPayload.attachments.forEach(function(fileUrl, i){
        createArgs['attachment_' + i] = fileUrl == null ? '' : String(fileUrl);
      });

      console.log('[LIFE DCR create_request scalar args]', createArgs);

      var res = await call('create_request', createArgs);
      var requestName=res.request||res.name||'';
      toast('Created '+requestName,'ok');
      await loadRequests({silent:true});
      if(canApprove())await loadApprovals();
      calculateDashboard();
      await go('requests');
      if(requestName)setTimeout(function(){openRequest(requestName);},120);
    }catch(e){
      console.error('[LIFE DCR create_request]',e);
      toast(e.message,'err');
    }finally{
      if(btn){btn.disabled=false;btn.textContent='Submit Correction Request';}
    }
  }

  function openModal(title,sub,body,foot,cls){
    var ov=byId('ov'),
        modal=byId('modal'),
        mt=byId('m-title'),
        ms=byId('m-sub'),
        mb=byId('m-body'),
        mf=byId('m-foot');

    if(!ov||!modal||!mt||!ms||!mb||!mf){
      console.error('[LIFE DCR modal] Required modal elements are missing.');
      return;
    }

    mt.innerHTML=title||'Details';
    ms.innerHTML=sub||'';
    mb.innerHTML=body||'';
    mf.innerHTML=foot||'<button class="btn" type="button" onclick="lifeDCR.closeModal()">Close</button>';

    modal.className='modal'+(cls?' '+cls:'');
    modal.style.display='flex';
    modal.style.visibility='visible';
    modal.style.opacity='1';

    ov.classList.add('on');
    ov.setAttribute('aria-hidden','false');

    document.documentElement.classList.add('life-dcr-modal-open');
    document.body.classList.add('life-dcr-modal-open');

    ov.scrollTop=0;
    mb.scrollTop=0;

    window.requestAnimationFrame(function(){
      var closeBtn=modal.querySelector('.x');
      if(closeBtn){
        closeBtn.setAttribute('tabindex','0');
        closeBtn.setAttribute('role','button');
        closeBtn.setAttribute('aria-label','Close');
      }
      var first=modal.querySelector('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]');
      if(first&&first.focus){
        try{first.focus({preventScroll:true});}catch(e){try{first.focus();}catch(x){}}
      }
    });
  }

  function closeModal(){
    var ov=byId('ov'),
        modal=byId('modal'),
        mb=byId('m-body'),
        mf=byId('m-foot');

    if(ov){
      ov.classList.remove('on');
      ov.setAttribute('aria-hidden','true');
      ov.scrollTop=0;
    }

    if(modal){
      modal.style.display='';
      modal.style.visibility='';
      modal.style.opacity='';
      modal.className='modal';
    }

    if(mb)mb.innerHTML='';
    if(mf)mf.innerHTML='<button class="btn" type="button" onclick="lifeDCR.closeModal()">Close</button>';

    document.documentElement.classList.remove('life-dcr-modal-open');
    document.body.classList.remove('life-dcr-modal-open');
  }

  async function applyModal(name){
  try{
    // Do NOT setBusy() — it wipes #wrap and leaves the spinner forever.
    var res=await call('get_request',{request:name});
    var doc=res.request||{};

    if(doc.status!=='Approved'){
      toast('This request is not approved ('+esc(doc.status)+')','wn');
      if(S.route==='post') await go('post');
      else if(S.route==='detail') await openRequest(name);
      else if(S.route==='requests') await go('requests');
      else if(S.route==='dash') await go('dash');
      return;
    }

    var changes=doc.changes||[];
    if(!changes.length){
      toast('This request has no change rows to post','err');
      if(S.route==='post') await go('post');
      else if(S.route==='detail') await openRequest(name);
      return;
    }

    var isCancel = changes.some(function(c){
      return c.field_name==='#cancel' && String(c.approved_value||c.requested_value||'')==='Cancelled';
    });

    var body='';

    if(isCancel){
      body+='<div class="note n-c" style="margin-bottom:12px">'
        +'<b>This will cancel the source document</b>'
        +'Posting will issue a cancel on '+esc(doc.source_doctype)+' <b>'+esc(doc.source_document)+'</b>. '
        +'Any downstream accounting entries depending on it will be affected. This cannot be undone from this page.</div>';
    } else {
      body+='<div class="note n-g" style="margin-bottom:12px">'
        +'<b>Writing the final approved values</b>'
        +'The values below will be written into '+esc(doc.source_doctype)+' <b>'+esc(doc.source_document)+'</b>. '
        +'Any approver revision is already reflected in the final value.</div>';
    }

    body+='<div class="tw"><table class="life-diff"><thead><tr>'
      +'<th>Field</th><th>Before</th><th>Requested</th><th>Final approved</th></tr></thead><tbody>';

    changes.forEach(function(c){
      var finalVal = (c.approved_value != null && String(c.approved_value)!=='')
        ? c.approved_value : c.requested_value;
      body+='<tr><td><b>'+esc(c.field_label||c.field_name)+'</b>'
        +'<div class="sm2 mono">'+esc(c.field_name||'')+'</div></td>'
        +'<td class="old">'+esc(c.old_value||'')+'</td>'
        +'<td class="req">'+esc(c.requested_value||'')+'</td>'
        +'<td class="final"><b>'+esc(finalVal==null?'':finalVal)+'</b></td></tr>';
    });

    body+='</tbody></table></div>';

    body+='<div class="fg" style="margin-top:12px">'
      +'<label>Posting remarks</label>'
      +'<input id="post-remarks" placeholder="Day-book reference, IT ticket, reason for override — optional">'
      +'</div>';

    if(isCancel){
      body+='<label style="display:flex;gap:8px;align-items:flex-start;margin-top:8px">'
        +'<input type="checkbox" id="post-confirm">'
        +'<span class="sm2">I have verified the source document and understand this will cancel it.</span>'
        +'</label>';
    }

    var foot='<button class="btn" type="button" onclick="lifeDCR.closeModal()">Cancel</button>'
      +'<button class="btn '+(isCancel?'d':'p')+'" id="post-go" type="button" '
      +'onclick="lifeDCR.doApply(\''+attr(name)+'\','+(isCancel?'true':'false')+')">'
      +'Post to source document</button>';

    openModal('Post correction to source record', name, body, foot, 'wide');

  }catch(e){
    console.error('[LIFE DCR applyModal]',e);
    toast(e.message||'Unable to load request','err');
  }
}

async function doApply(name, requireConfirm){
  var remarksEl=byId('post-remarks');
  var remarks=clean(remarksEl?remarksEl.value:'');

  if(requireConfirm){
    var cb=byId('post-confirm');
    if(!cb||!cb.checked){ toast('Tick the confirmation box before posting','wn'); return; }
  }

  if(!window.confirm('Post this correction to the source document now?\n\n'+name
      +'\n\nThis writes to the live ERPNext record and cannot be undone.')) return;

  var btn=byId('post-go');
  if(btn){ btn.disabled=true; btn.textContent='Posting…'; }

  var safetyTimer=setTimeout(function(){
    var b=byId('post-go');
    if(b){ b.disabled=false; b.textContent='Post to source document'; }
    toast('The server did not respond. Check your connection and try again.','err');
  },30000);

  try{
    var res=await call('apply_request',{ request:name, posting_remarks:remarks });
    if(safetyTimer) clearTimeout(safetyTimer);
    closeModal();

    var applied=(res&&res.applied)||[];
    var skipped=(res&&res.skipped)||[];
    var msg='<div class="note n-g" style="margin-bottom:10px">'
      +'<b>Posted successfully</b>'
      +'Request '+esc(res.request||name)+' is now <b>'+esc(res.status||'Posted')+'</b>.'
      +(res.posted_on? ' Posted on '+esc(fmtDT(res.posted_on))+'.' :'')
      +'</div>';

    if(applied.length){
      msg+='<div class="sec"><b>Fields written</b><i></i></div>'
        +'<div class="tw"><table class="life-diff"><tbody>'
        +applied.map(function(x){return '<tr><td class="final">'+esc(x)+'</td></tr>'}).join('')
        +'</tbody></table></div>';
    }
    if(skipped.length){
      msg+='<div class="note n-w" style="margin-top:10px">'
        +'<b>Some fields were not written</b>'
        +skipped.map(function(x){return esc(x)}).join('<br>')
        +'<br>Review the source document and raise a fresh correction if needed.</div>';
    }

    openModal('Posting result', name, msg,
      '<button class="btn" type="button" onclick="lifeDCR.closeModal()">Close</button>'
      +'<button class="btn p" type="button" onclick="lifeDCR.closeModal();lifeDCR.go(\'post\')">Back to post queue</button>',
      'wide');

    toast('Posted '+name+(skipped.length? ' with '+skipped.length+' skipped field(s)':''),
      skipped.length? 'wn':'ok');

    await loadRequests({silent:true});
    if(canApprove()) await loadApprovals();
    calculateDashboard();
    renderNav();
    updateNavBadges();

    if(S.route==='detail' && S.currentRequest && S.currentRequest.name===name){
      await openRequest(name);
    } else if(S.route==='post'){
      renderApprovedForPost();
    } else if(S.route==='dash'){
      renderDashboard();
    }
  }catch(e){
    if(safetyTimer) clearTimeout(safetyTimer);
    console.error('[LIFE DCR doApply]', e);

    var raw = clean(e && e.message ? e.message : 'Posting failed');

    var isLink  = raw.indexOf('[LINK]')  === 0;
    var isStale = raw.indexOf('[STALE]') === 0;
    var isState = raw.indexOf('[STATE]') === 0;
    var isDup   = raw.indexOf('[DUP]')   === 0;
    var isWrite = raw.indexOf('[WRITE]') === 0;
    var isPerm  = raw.indexOf('[PERM]')  === 0;

    var plain = raw
      .replace(/^\[LINK\]\s*/,  '')
      .replace(/^\[STALE\]\s*/, '')
      .replace(/^\[STATE\]\s*/, '')
      .replace(/^\[DUP\]\s*/,   '')
      .replace(/^\[WRITE\]\s*/, '')
      .replace(/^\[PERM\]\s*/,  '');

    var title, kind, hint;

    if (isLink) {
      title = 'A corrected value points to a record that does not exist';
      kind  = 'n-w';
      hint  = 'Nothing was written. The correction is still Approved. '
            + 'Create the missing record in ERPNext, or send the request '
            + 'back to the branch so a fresh correction can be raised '
            + 'with a valid value.';
    } else if (isStale) {
      title = 'The source document has changed since this request was raised';
      kind  = 'n-w';
      hint  = 'Nothing was written. The correction is still Approved. '
            + 'Re-verify the source document, or ask a DCR Admin to '
            + 'override the concurrency guard.';
    } else if (isState) {
      title = 'This request cannot be posted';
      kind  = 'n-i';
      hint  = 'The request is no longer in the Approved state. It may '
            + 'already have been posted, rejected, or sent back. Reload '
            + 'the queue to see the current status.';
    } else if (isDup) {
      title = 'Already posted';
      kind  = 'n-i';
      hint  = 'This request was posted earlier. Nothing else needs to '
            + 'be done. Reload the queue to see the posting reference.';
    } else if (isWrite) {
      title = 'The source document rejected the corrected values';
      kind  = 'n-c';
      hint  = 'Nothing was written. The correction is still Approved. '
            + 'Open the source document, check the field rules and '
            + 'mandatory fields, then try again or send the request back.';
    } else if (isPerm) {
      title = 'Your role cannot post this correction';
      kind  = 'n-c';
      hint  = 'Posting is restricted to Accounts, COO, or a System '
            + 'Manager. Nothing was written.';
    } else {
      title = 'Posting failed';
      kind  = 'n-c';
      hint  = 'Nothing was written. The correction remains Approved. '
            + 'Share this message with IT if the cause is not obvious.';
    }

    var body =
      '<div class="note ' + kind + '" style="margin-bottom:10px">'
        + '<b>' + esc(title) + '</b>' + esc(hint)
      + '</div>'

      + '<div class="life-kvgrid" style="margin-bottom:10px">'
        + '<div class="kv"><span>Request</span>'
          + '<b class="mono">' + esc(name) + '</b></div>'
        + '<div class="kv"><span>Status</span>'
          + '<b>Approved &middot; unchanged</b></div>'
      + '</div>'

      + '<div class="sec"><b>Server message</b><i></i></div>'
      + '<pre style="white-space:pre-wrap;'
        + 'background:#FDF3F1;border:1px solid #F0D5CF;'
        + 'border-radius:7px;padding:10px;font-size:12px;'
        + 'color:#7A211A;max-height:260px;overflow:auto">'
        + esc(plain)
      + '</pre>';

    openModal(
      title,
      name,
      body,
      '<button class="btn" type="button" '
        + 'onclick="lifeDCR.closeModal()">Close</button>'

      + '<button class="btn p" type="button" '
        + 'onclick="lifeDCR.closeModal();lifeDCR.openRequest(\''
        + attr(name) + '\')">Open the request</button>'

      + '<button class="btn" type="button" '
        + 'onclick="lifeDCR.closeModal();lifeDCR.go(\'post\')">'
        + 'Back to post queue</button>',
      'wide'
    );

    var b2 = byId('post-go');
    if (b2) { b2.disabled = false; b2.textContent = 'Post to source document'; }
  }
}

  async function openRequest(name){
    try{
      setBusy('Loading '+name+'…');
      var res=await call('get_request',{request:name});
      S.currentRequest=res.request||{};
      S.currentCanAct=!!res.can_act;
      S.route='detail';
      S.openGroup='CORRECTION DESK';
      renderNav();
      renderRequestPage();
      window.scrollTo({top:0,behavior:'smooth'});
    }catch(e){
      console.error('[LIFE DCR open request]',e);
      toast(e.message||'Unable to open request','err');
      if(S.route==='detail')await go('requests');
    }
  }

  function renderApprovalFlow(doc){
    var rows=(doc.approvals||[]).slice().sort(function(a,b){return Number(a.stage_no||0)-Number(b.stage_no||0);});
    if(!rows.length)return emptyBlock('No approval stages','This request has no approval child rows.');
    return '<div class="life-flow">'+rows.map(function(a){
      var d=clean(a.decision)||'Pending',
          active=(doc.status==='Pending Approval'&&clean(doc.current_approver_role)===clean(a.required_access_role));
      var icon=d==='Approved'?'✓':d==='Rejected'?'✕':d==='Skipped'?'—':'●';
      return '<div class="life-approval-item '+(active?'life-current-stage':'')+'">'+
        '<div class="top"><b>'+icon+' '+esc(a.required_access_role||a.required_role||a.stage||'Approver')+'</b>'+decisionTag(d)+'</div>'+
        '<div class="meta">'+esc(a.approver_name||a.approver_user||(active?'Pending now':'Waiting'))+(a.acted_on?' · '+fmtDT(a.acted_on):'')+'</div>'+
        (a.remarks?'<div class="life-approval-remark">'+esc(a.remarks)+'</div>':'')+
      '</div>';
    }).join('')+'</div>';
  }

  function renderTimeline(doc){
    var h='<div class="life-timeline">';
    h+='<div class="life-tl-item done"><span class="life-tl-dot"></span><div><b>Request submitted — '+esc(doc.requested_by_name||doc.requested_by||'')+'</b><span>'+fmtDT(doc.requested_on||doc.creation)+'</span>'+(doc.reason?'<p>'+esc(doc.reason)+'</p>':'')+'</div></div>';

    var pendingShown=false;
    (doc.approvals||[]).slice().sort(function(a,b){return Number(a.stage_no||0)-Number(b.stage_no||0);}).forEach(function(a){
      var roleName=a.required_access_role||a.required_role||a.stage||'Approver';
      if(a.decision&&a.decision!=='Pending'){
        h+='<div class="life-tl-item '+(a.decision==='Rejected'?'reject':'done')+'"><span class="life-tl-dot"></span><div>'+
          '<b>'+esc(a.decision)+' — '+esc(a.approver_name||a.approver_user||roleName)+'</b>'+
          '<span>'+fmtDT(a.acted_on)+' · stage '+esc(roleName)+'</span>'+
          (a.remarks?'<p>'+esc(a.remarks)+'</p>':'')+
        '</div></div>';
      }else if(!pendingShown && doc.status==='Pending Approval' && clean(doc.current_approver_role)===clean(a.required_access_role)){
        pendingShown=true;
        h+='<div class="life-tl-item pending"><span class="life-tl-dot"></span><div>'+
          '<b>Waiting with '+esc(roleName)+'</b>'+
          '<span>Current approval stage</span>'+
        '</div></div>';
      }
    });

    if(doc.status==='Approved'){
      h+='<div class="life-tl-item done"><span class="life-tl-dot"></span><div><b>Final approval complete</b><span>'+fmtDT(doc.final_approved_on)+'</span><p>Approved — waiting for the separate posting engine.</p></div></div>';
    }
    if(doc.status==='Rejected'){
      h+='<div class="life-tl-item reject"><span class="life-tl-dot"></span><div><b>Request rejected</b><span>Approval chain closed</span></div></div>';
    }
    h+='</div>';
    return h;
  }

  function renderRequestPage(){
    var doc=S.currentRequest||{}, canAct=!!S.currentCanAct;
    if(!doc.name){
      byId('wrap').innerHTML=ph('CORRECTION DESK','Request not loaded','Open a request from All Requests or My Approval Queue.','<button class="btn" onclick="lifeDCR.go(\'requests\')">Back to requests</button>');
      return;
    }

    var backRoute=(canApprove()&&doc.status==='Pending Approval'&&clean(doc.current_approver_role)===clean(role()))?'approvals':'requests';
    var h=ph(
      'CORRECTION DESK · REQUEST DETAIL',
      doc.name,
      esc(doc.source_doctype||'')+' · '+esc(doc.source_document||'')+(doc.branch?' · '+esc(doc.branch):''),
      '<button class="btn" onclick="lifeDCR.go(\''+backRoute+'\')">← Back</button>'
    );

    h+='<div class="life-detail-top">'+
      '<div class="life-detail-title"><div><b>'+esc(doc.source_display_name||doc.source_document||doc.name)+'</b><span>'+esc(doc.category||'')+' · raised '+fmtDT(doc.requested_on||doc.creation)+'</span></div>'+
      '<div class="life-statusline">'+statusTag(doc.status)+(Number(doc.is_on_hold)?'<span class="hold">🔒 Source on hold</span>':'')+'</div></div>'+
    '</div>';

    h+=sectionHead('Request & source','what is being corrected');
    h+='<div class="card acc"><div class="body"><div class="life-kvgrid">'+
      '<div class="kv"><span>Source DocType</span><b>'+esc(doc.source_doctype||'—')+'</b></div>'+
      '<div class="kv"><span>Source Document</span><b class="mono">'+esc(doc.source_document||'—')+'</b></div>'+
      '<div class="kv"><span>Branch</span><b>'+esc(doc.branch||'—')+'</b></div>'+
      '<div class="kv"><span>Requested By</span><b>'+esc(doc.requested_by_name||doc.requested_by||'—')+'</b></div>'+
      '<div class="kv"><span>Requester Role</span><b>'+esc(doc.access_role_at_creation||doc.requester_designation||'—')+'</b></div>'+
      '<div class="kv"><span>Current Stage</span><b>'+esc(doc.workflow_stage||doc.current_approver_role||'—')+'</b></div>'+
    '</div><div class="note n-m" style="margin-top:12px"><b>Reason</b>'+esc(doc.reason||'—')+'</div></div></div>';

    h+=sectionHead('Before → Requested → Approved','the exact values under approval');
    var changes=doc.changes||[];
    if(changes.length){
      h+='<div class="card acc-g"><div class="body flush"><div class="tw"><table class="life-diff"><thead><tr><th>Field</th><th>Before</th><th>Requested</th><th>Approved value</th></tr></thead><tbody>'+
      changes.map(function(x,i){
        var finalVal=(x.approved_value!=null&&String(x.approved_value)!=='')?x.approved_value:x.requested_value;
        var finalHtml=canAct?'<input class="life-approval-value" id="approved-change-'+i+'" data-row-name="'+attr(x.name||'')+'" data-field-name="'+attr(x.field_name||'')+'" value="'+attr(finalVal==null?'':finalVal)+'">':'<b>'+esc(finalVal==null?'':finalVal)+'</b>';
        return '<tr><td><b>'+esc(x.field_label||x.field_name)+'</b><div class="sm2 mono">'+esc(x.field_name||'')+'</div></td>'+
          '<td class="old">'+esc(x.old_value||'')+'</td><td class="req">'+esc(x.requested_value||'')+'</td><td class="final">'+finalHtml+'</td></tr>';
      }).join('')+'</tbody></table></div>'+
      (canAct?'<div class="life-inline-help">You can change the <b>Approved value</b> before choosing “Approve with my figures”.</div>':'')+
      '</div></div>';
    }else{
      h+=card('No change rows','',emptyBlock('No correction lines','This request has no LIFE Data Correction Change rows.'),{cls:'acc'});
    }

    h+=sectionHead('Supporting evidence','documents attached to the request');
    var files=[doc.attachment_1,doc.attachment_2,doc.attachment_3].filter(Boolean);
    h+='<div class="card"><div class="body">'+
      (files.length?'<div class="life-file-row">'+files.map(function(f,i){return '<a class="filechip" href="'+attr(f)+'" target="_blank" rel="noopener">📎 '+esc(String(f).split('/').pop()||('Attachment '+(i+1)))+'</a>';}).join('')+'</div>':'<span class="sm2">No attachments</span>')+
    '</div></div>';

    h+=sectionHead('Approval flow','configured approval chain');
    h+='<div class="card"><div class="body">'+renderApprovalFlow(doc)+'</div></div>';

    h+=sectionHead('Approval timeline','who approved, when, and what they said');
    h+='<div class="card"><div class="body">'+renderTimeline(doc)+'</div></div>';

    h+=sectionHead('Your decision',canAct?((S.context||{}).is_dcr_admin?'admin override · you may act on the current stage':'you are the '+esc(role())+' approver on this request'):'request action status');
    if(canAct&&doc.status==='Pending Approval'){
      h+='<div class="card life-decision-card"><div class="body">'+
        ((S.context||{}).is_dcr_admin?'<div class="note n-i" style="margin-bottom:10px"><b>Admin override</b>You may approve or reject this request even though the current stage is '+esc(doc.current_approver_role||doc.workflow_stage||'another role')+'. Your user will be recorded in the audit trail.</div>':'')+
        '<div class="note n-a"><b>Four ways to close this stage</b>Approve as asked · approve with the figures you decide · send it back for more information · reject it. The source data is still unchanged until the separate posting step runs.</div>'+
        '<div class="life-decision-buttons">'+
          '<button class="btn g lg" onclick="lifeDCR.quickDecision(\''+attr(doc.name)+'\',\'Approved\',0)">Approve as requested</button>'+
          '<button class="btn gold lg" onclick="lifeDCR.quickDecision(\''+attr(doc.name)+'\',\'Approved\',1)">Approve with my figures</button>'+
          '<button class="btn lg" disabled title="Send Back workflow will be enabled after the resubmit flow is added">Send back for information</button>'+
          '<button class="btn d lg" onclick="lifeDCR.quickDecision(\''+attr(doc.name)+'\',\'Rejected\',0)">Reject</button>'+
        '</div>'+
      '</div></div>';
    }else if(doc.status==='Approved'){
      if(canApply()){
        h+=sectionHead('Post this correction','fully approved — the source data has not changed yet');
        h+='<div class="card acc-g"><div class="body">'
          +'<div class="note n-g" style="margin-bottom:11px"><b>Cleared by all approval stages</b>'
          +'Posting writes the final approved values into '+esc(doc.source_doctype)+' '
          +'<b>'+esc(doc.source_document)+'</b>, releases the hold, and closes the request. This cannot be undone.</div>'
          +'<div class="btnrow">'
            +'<button class="btn p big" type="button" onclick="lifeDCR.applyModal(\''+attr(doc.name)+'\')">Apply to the source document</button>'
          +'</div></div></div>';
      } else {
        h+='<div class="note n-g"><b>Approved — To Apply</b>'
          +'The approval chain is complete. Posting is restricted to Accounts, COO, or a System Manager.</div>';
      }
    }else if(doc.status==='Rejected'){
      h+='<div class="note n-c"><b>Rejected</b>The approval chain has stopped.</div>';
    }else{
      h+='<div class="note n-i"><b>No action required from your role</b>This request is currently waiting with '+esc(doc.current_approver_role||doc.workflow_stage||'another stage')+'.</div>';
    }

    h+=sectionHead('Messages / remarks','real request and approval comments');
    var remarks=[];
    if(doc.reason)remarks.push({who:doc.requested_by_name||doc.requested_by||'Requester',when:doc.requested_on||doc.creation,text:doc.reason,type:'Request'});
    (doc.approvals||[]).forEach(function(a){
      if(a.remarks)remarks.push({who:a.approver_name||a.approver_user||a.required_access_role||'Approver',when:a.acted_on,text:a.remarks,type:a.decision||'Approval'});
    });
    h+='<div class="card"><div class="body">'+(remarks.length?'<div class="life-message-list">'+remarks.map(function(m){return '<div class="life-message"><div><b>'+esc(m.who)+'</b><span>'+esc(m.type)+' · '+fmtDT(m.when)+'</span></div><p>'+esc(m.text)+'</p></div>';}).join('')+'</div>':emptyBlock('No remarks yet','Approval remarks will appear here as the request moves through the chain.'))+'</div></div>';

    byId('wrap').innerHTML=h;
    decoratePage();
  }

  function collectApprovedChanges(){
    var out=[];
    document.querySelectorAll('#wrap .life-approval-value').forEach(function(el){
      out.push({
        name:el.getAttribute('data-row-name')||'',
        field_name:el.getAttribute('data-field-name')||'',
        approved_value:el.value
      });
    });
    return out;
  }

  function quickDecision(name,decision,useFigures){
    if(decision==='Approved'){
      S.pendingApprovedChanges=useFigures?collectApprovedChanges():[];
    }else{
      S.pendingApprovedChanges=[];
    }
    decisionPrompt(name,decision);
  }

  function decisionPrompt(name,decision){
    var label=decision==='Approved'?'Approve':'Reject';
    if(decision!=='Approved')S.pendingApprovedChanges=[];
    var body='<div class="note '+(decision==='Rejected'?'n-c':'n-g')+'"><b>'+label+' '+esc(name)+'</b>'+(decision==='Approved'?'The request will move to the next configured approval stage.':'The remaining approval process will stop.')+'</div><div class="fg" style="margin-top:12px"><label>Remarks <span class="rq">*</span></label><textarea id="decision-remarks" rows="4" placeholder="Remarks are mandatory"></textarea></div>';
    var foot='<button class="btn" onclick="lifeDCR.closeModal()">Cancel</button><button id="decision-save-btn" class="btn '+(decision==='Rejected'?'d':'p')+'" onclick="lifeDCR.submitDecision(\''+attr(name)+'\',\''+decision+'\')">'+label+'</button>';
    openModal(label+' Request',name,body,foot,'narrow');
  }

  async function submitDecision(name,decision){
    var remarks=clean(byId('decision-remarks')?byId('decision-remarks').value:'');
    if(!remarks){toast('Remarks are mandatory.','wn');if(byId('decision-remarks'))byId('decision-remarks').focus();return;}
    if(S.decisionSaving[name]){toast('This approval action is already being saved.','wn');return;}

    var msg=(decision==='Approved'?'APPROVE':'REJECT')+' '+name+'?\n\nRemarks: '+remarks;
    if(!window.confirm(msg))return;

    S.decisionSaving[name]=true;
    var btn=byId('decision-save-btn');if(btn){btn.disabled=true;btn.textContent='Saving…';}
    try{
      var args={request:name,decision:decision,remarks:remarks};
      if(decision==='Approved'&&S.pendingApprovedChanges&&S.pendingApprovedChanges.length)args.approved_changes=JSON.stringify(S.pendingApprovedChanges);
      var res=await call('decision',args);
      toast(name+' · '+(res.status||decision),'ok');
      closeModal();
      await loadRequests({silent:true});
      if(canApprove())await loadApprovals();
      calculateDashboard();
      renderNav();
      if(S.route==='detail'){
        setTimeout(function(){openRequest(name);},120);
      }else if(S.route==='approvals')renderApprovals();
      else if(S.route==='dash')renderDashboard();
      else if(S.route==='requests')renderRequests();
    }catch(e){
      console.error('[LIFE DCR decision]',e);toast(e.message,'err');
    }finally{
      delete S.decisionSaving[name];
      S.pendingApprovedChanges=[];
      if(btn){btn.disabled=false;btn.textContent=decision==='Approved'?'Approve':'Reject';}
    }
  }

  async function applyRequest(name, remarks){
      return call('apply_request', {
        request: name,
        posting_remarks: remarks || ''
      });
    }
  function toggleMenu(){var s=byId('life-dcr-side');if(s)s.classList.toggle('show');}

  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){bootstrap();});}else{bootstrap();}

  return {
    go:go, toggleGroup:toggleGroup, toggleMenu:toggleMenu, closeModal:closeModal, openRequest:openRequest,
    renderRequestPage:renderRequestPage, quickDecision:quickDecision,
    filterStatus:filterStatus, setPage:setPage, applyRequestFilters:applyRequestFilters,
    clearRequestFilters:clearRequestFilters, ruleChanged:ruleChanged, searchSource:searchSource,
    selectSource:selectSource, uploadSelected:uploadSelected, submitRequest:submitRequest,
    decisionPrompt:decisionPrompt, submitDecision:submitDecision, applyRequest:applyRequest,
    applyModal:applyModal, doApply:doApply,
    helpModal:helpModal,setZoom:setZoom,secJump:secJump,secGo:secGo,secToggle:secToggle,secAll:secAll,tipToggle:tipToggle,tipAll:tipAll
  };
})();
